// Conteúdo do motor de BI copiado para o app exportado (lib/bi/*, lib/schemaResolver.ts, lib/relationPath*.ts).

export const BI_RUNTIME_FILES: Record<string, string> = {
  "lib/bi/widgetPlan.ts": "/**\n * Planejador de consulta de um widget de BI.\n *\n * Recebe o widget, o modelo de dados (tabelas, campos, relações) e o contexto (filtros da tela, período, banco) e devolve\n * O QUE executar: o SQL agregado (e o do período anterior, no KPI com comparação), o SQL de linhas cruas da reserva, ou\n * a mensagem de erro para o usuário. Não executa nada: é função pura. O painel em execução envia o resultado pelo túnel;\n * o app exportado executa no servidor, diretamente no banco. Assim a lógica de tabelas, JOINs mínimos, filtros e\n * recursos do widget existe uma vez só.\n */\nimport { getPkColumn, warnInferredReference } from '../schemaResolver'\nimport { resolveRelations, resolveAllJoins, buildJoinSql, type JoinStep } from '../relationPathFinder'\nimport { findAlternativePaths, pathSignature } from '../relationPaths'\nimport { parseFormulaAst } from './safeFormula'\nimport { buildAggregateQuery, filterConditionSql, quoteFor, type SqlDialect, type BiCondition, type BiConditionOp, type BiColKind } from './queryBuilder'\nimport { resolveFkLabel } from './fkLabel'\nimport { biFieldKind } from './columnKind'\nimport { previousRange, nextDay, type PeriodRange } from './period'\nimport type { BiWidget } from './widget'\nimport type { GroupInfo } from './interaction'\n\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/\nconst FILTER_KEY = /^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z_][A-Za-z0-9_]*)?$/\n\nexport interface PlanInput {\n  widget: BiWidget\n  /** tabelas do projeto, cada uma com `fields` (array ou objeto) */\n  models: any[] | Record<string, any>\n  /** relações do projeto como vêm do banco (com ids de model e campo) */\n  relations: any[]\n  /** dialeto do SQL agregado; null = o banco não suporta (cai nas linhas cruas) */\n  dialect: SqlDialect | null\n  /** JOINs configurados no caso de uso (legado) */\n  layoutJoins?: any[]\n  /** filtros da tela: \"coluna\" ou \"tabela.coluna\" → texto digitado (viram \"contém\") */\n  screenFilters?: Record<string, string>\n  /** período efetivo do widget (já resolvido pelo chamador) ou null */\n  period?: PeriodRange | null\n  /** pula o SQL agregado (usado depois que ele falhou no banco) */\n  legacy?: boolean\n  /** erro do banco quando o SQL agregado falhou */\n  failureReason?: string\n  /** schema usado quando a tabela não declara um */\n  projectSlug?: string\n  rawRowLimit: number\n  maxGroups: number\n}\n\nexport interface WidgetPlan {\n  kind: 'agg' | 'raw' | 'error'\n  tableName: string\n  schemaName: string\n  /** SQL a executar (kind agg ou raw) */\n  sql?: string\n  /** teto de linhas que o executor deve aceitar */\n  limit?: number\n  /** KPI com comparação: SQL do período anterior */\n  prev?: { sql: string; limit: number }\n  /** o widget pede comparação com o período anterior */\n  compare: boolean\n  /** como o gráfico está agrupado: o campo a filtrar quando alguém clica numa barra/fatia (Fase 4) */\n  group?: GroupInfo\n  /** mensagem para o usuário (kind error) */\n  message?: string\n  warnings: string[]\n}\n\ntype Col = { table: string; column: string }\n\nexport function planWidgetQuery(input: PlanInput): WidgetPlan {\n  const { widget, dialect, layoutJoins = [], screenFilters = {}, period = null, legacy = false } = input\n  const allModels: any[] = Array.isArray(input.models) ? input.models : Object.values(input.models || {})\n  const warnings: string[] = []\n\n  const model = allModels.find(m => String(m.id) === String(widget.model_id))\n  const tableName: string | null =\n    model?.db_table_name || (typeof widget.model_id === 'string' && widget.model_id !== 'undefined' && !widget.model_id.includes('-') ? widget.model_id : null)\n  const schemaName: string = model?.db_schema_name || input.projectSlug || 'public'\n\n  const fail = (message: string): WidgetPlan => ({ kind: 'error', tableName: tableName || '', schemaName, compare: false, message, warnings })\n\n  if (!tableName) return fail('Tabela não encontrada')\n  const mainTable: string = tableName\n\n  // Todo campo do widget é \"TABELA.COLUNA\": sem o nome da tabela, uma coluna repetida (STATUS, NOME...) poderia vir de qualquer tabela\n  {\n    const isF = !!widget.use_formula\n    const unqualified: string[] = []\n    const check = (label: string, v?: string) => { if (v && !String(v).includes('.')) unqualified.push(`${label} (\"${v}\")`) }\n    check('Agrupar por', widget.group_by)\n    if (!isF && widget.field && widget.field !== '*') check('Campo do valor', widget.field)\n    check('Segmentar por', widget.series_by)\n    check('Divisor', widget.divide_by?.field)\n    check('Campo do período', widget.period_field)\n    ;(widget.conditions || []).forEach((c, i) => check(`Filtro ${i + 1}`, c.field))\n    if (isF && widget.field) {\n      const ast = parseFormulaAst(String(widget.field))\n      const walk = (n: any): boolean => !n ? false : n.t === 'field' ? !n.table : n.t === 'neg' ? walk(n.a) : n.t === 'bin' ? walk(n.a) || walk(n.b) : n.t === 'fn' ? n.args.some(walk) : false\n      if (walk(ast)) unqualified.push('Fórmula')\n    }\n    if (unqualified.length > 0) {\n      return fail(`Reabra o widget e selecione novamente (sem a tabela do campo): ${unqualified.join(', ')}`)\n    }\n  }\n\n  const Q = quoteFor(dialect ?? 'postgres')\n  const qCol = (table: string, column: string) => `${Q(table)}.${Q(column)}`\n\n  const isFormula = widget.use_formula || (widget.field?.includes('*') || widget.field?.includes('+') || widget.field?.includes('/') || widget.field?.includes('-'))\n\n  // Colunas que o caminho de linhas cruas precisa trazer\n  let selectStr = '*'\n  if (!isFormula && widget.field !== '*') {\n    const fieldMeta = model?.fields?.find((f: any) => String(f.id) === String(widget.field))\n    selectStr = fieldMeta?.db_column_name || widget.field || '*'\n  } else if (isFormula && widget.field) {\n    const formulaStr = String(widget.field)\n    const matches = formulaStr.match(/[a-zA-Z_][a-zA-Z0-9_]*(?:\\.[a-zA-Z_][a-zA-Z0-9_]*)?/g) || []\n    const keywords = ['SUM', 'AVG', 'MIN', 'MAX', 'COUNT', 'AND', 'OR', 'NOT', 'NULL', 'IS', 'TRUE', 'FALSE']\n    const cols = matches.filter(m => !keywords.includes(m.toUpperCase()) && isNaN(Number(m)))\n    if (cols.length > 0) selectStr = [...new Set(cols)].join(', ')\n  }\n\n  let groupCol = widget.group_by\n  if (widget.group_by && !selectStr.includes(widget.group_by)) {\n    const parts = widget.group_by.split('.')\n    const targetTableName = parts.length > 1 ? parts[0] : null\n    const targetFieldName = parts.length > 1 ? parts[1] : widget.group_by\n    for (const m of allModels) {\n      if (targetTableName && m.db_table_name !== targetTableName) continue\n      const fields = Array.isArray(m.fields) ? m.fields : Object.values(m.fields || {})\n      const found = (fields as any[]).find(f => String(f.id) === String(targetFieldName) || f.db_column_name === targetFieldName || f.name === targetFieldName)\n      if (found) {\n        groupCol = `${m.db_table_name}.${found.db_column_name}`\n        break\n      }\n    }\n    if (typeof groupCol === 'string' && !selectStr.includes(groupCol)) {\n      selectStr = selectStr === '*' ? groupCol : `${selectStr}, ${groupCol}`\n    }\n  }\n\n  // JOINs: caminho mais curto no grafo de relações (ou o que o desenvolvedor escolheu)\n  const resolvedRelations = resolveRelations(input.relations || [], allModels)\n\n  // Tabelas citadas pelo widget (agrupamento, valor e JOINs manuais)\n  const referencedTables: string[] = []\n  if (typeof groupCol === 'string' && groupCol.includes('.')) referencedTables.push(groupCol.split('.')[0])\n  if (widget.field && typeof widget.field === 'string') {\n    const matches = widget.field.match(/[a-zA-Z0-9_]+\\.[a-zA-Z0-9_]+/g)\n    if (matches) matches.forEach(m => referencedTables.push(m.split('.')[0]))\n    else if (widget.field.includes('.')) referencedTables.push(widget.field.split('.')[0])\n  }\n  const legacyJoins = [...(widget.joins || []), ...layoutJoins]\n  legacyJoins.forEach((j: any) => {\n    const fromModel = allModels.find(m => String(m.id) === String(j.from) || m.db_table_name === j.from)\n    const toModel = allModels.find(m => String(m.id) === String(j.to) || m.db_table_name === j.to)\n    if (fromModel?.db_table_name) referencedTables.push(fromModel.db_table_name)\n    if (toModel?.db_table_name) referencedTables.push(toModel.db_table_name)\n  })\n\n  // caminhos de relação que o desenvolvedor escolheu no editor (tabela → caminho); a escolha só vale se ainda existir\n  const preferredPaths: Record<string, JoinStep[]> = {}\n  for (const [tbl, sig] of Object.entries(widget.relation_paths || {})) {\n    const hit = findAlternativePaths(resolvedRelations, mainTable, tbl).find(p => pathSignature(p) === sig)\n    if (hit) preferredPaths[tbl.toLowerCase()] = hit\n  }\n\n  // Monta os JOINs para um conjunto de tabelas. Chamada duas vezes: com tudo (linhas cruas, como antes) e só com as\n  // tabelas que o widget usa (SQL agregado, para não multiplicar linhas).\n  const resolveJoinSql = (referenced: string[], legacy: any[]) => {\n    let joinSql = ''\n    const joinedTables = new Set<string>([mainTable])\n\n    if (resolvedRelations.length > 0 && referenced.length > 0) {\n      const uniqueReferenced = [...new Set(referenced.filter(t => t !== mainTable))]\n      const steps = resolveAllJoins(resolvedRelations, mainTable, uniqueReferenced, preferredPaths)\n      joinSql += buildJoinSql(steps, undefined, Q)\n      steps.forEach(s => { joinedTables.add(s.fromTable); joinedTables.add(s.toTable) })\n    }\n\n    // JOINs configurados à mão (legado)\n    if (legacy.length > 0) {\n      const processJoins = () => {\n        let added = false\n        legacy.forEach((j: any) => {\n          const fromModel = allModels.find(m => String(m.id) === String(j.from) || m.db_table_name === j.from)\n          const toModel = allModels.find(m => String(m.id) === String(j.to) || m.db_table_name === j.to)\n          const fromTable = fromModel?.db_table_name || j.from || j.table\n          const toTable = toModel?.db_table_name || j.to || j.toTable\n          const fromField = fromModel?.fields?.find((f: any) => String(f.id) === String(j.local_field || j.local || j.localKey))?.db_column_name || j.local_field || j.local || j.localKey || getPkColumn(allModels, fromTable) || 'id'\n          const toField = toModel?.fields?.find((f: any) => String(f.id) === String(j.foreign_field || j.foreignKey))?.db_column_name || j.foreign_field || j.foreignKey || getPkColumn(allModels, toTable) || 'id'\n          if (!fromTable || !toTable) return\n          if (![fromTable, toTable, fromField, toField].every(x => IDENT.test(String(x)))) return\n          if (joinedTables.has(fromTable) && joinedTables.has(toTable)) return\n          if (!joinedTables.has(fromTable) && !joinedTables.has(toTable)) return\n          const newTable = joinedTables.has(fromTable) ? toTable : fromTable\n          joinSql += ` LEFT JOIN ${Q(newTable)} ON ${qCol(fromTable, fromField)} = ${qCol(toTable, toField)}`\n          joinedTables.add(newTable)\n          added = true\n        })\n        return added\n      }\n      let iterations = 0\n      while (processJoins() && iterations < 10) iterations++\n    }\n\n    // Auto-join heurístico: tabela ainda sem JOIN → procura uma chave estrangeira nos modelos\n    const missingTables = referenced.filter(t => !joinedTables.has(t) && t !== mainTable)\n    missingTables.forEach(refTable => {\n      if (!IDENT.test(refTable)) return\n      for (const jt of Array.from(joinedTables)) {\n        const jtModel = allModels.find(m => m.db_table_name === jt)\n        if (jtModel) {\n          const fields = Array.isArray(jtModel.fields) ? jtModel.fields : Object.values(jtModel.fields || {})\n          const isRel = (f: any) => (f.type === 'relation' && (f.relation?.table === refTable || f.relation_table === refTable)) || (!!f.foreign_key_table && String(f.foreign_key_table).toLowerCase() === String(refTable).toLowerCase())\n          const isRelByName = (f: any) => f.db_column_name === `${refTable}_id` || f.db_column_name === `${refTable.replace(/s$/, '')}_id`\n          const relField = (fields as any[]).find(isRel) || (() => { const g = (fields as any[]).find(isRelByName); if (g) warnInferredReference(g.db_column_name, refTable); return g })()\n          if (relField) {\n            const localCol = relField.db_column_name || 'id'\n            const foreignCol = relField.relation?.foreign_field || relField.relation_key || relField.foreign_key_column || getPkColumn(allModels, refTable) || 'id'\n            if (IDENT.test(jt) && IDENT.test(localCol) && IDENT.test(foreignCol)) {\n              joinSql += ` LEFT JOIN ${Q(refTable)} ON ${qCol(jt, localCol)} = ${qCol(refTable, foreignCol)}`\n              joinedTables.add(refTable)\n              break\n            }\n          }\n        }\n        const refModel = allModels.find(m => m.db_table_name === refTable)\n        if (refModel) {\n          const fields = Array.isArray(refModel.fields) ? refModel.fields : Object.values(refModel.fields || {})\n          const isRelReverse = (f: any) => (f.type === 'relation' && (f.relation?.table === jt || f.relation_table === jt)) || (!!f.foreign_key_table && String(f.foreign_key_table).toLowerCase() === String(jt).toLowerCase())\n          const isRelReverseByName = (f: any) => f.db_column_name === `${jt}_id` || f.db_column_name === `${jt.replace(/s$/, '')}_id`\n          const relField = (fields as any[]).find(isRelReverse) || (() => { const g = (fields as any[]).find(isRelReverseByName); if (g) warnInferredReference(g.db_column_name, jt); return g })()\n          if (relField) {\n            const localCol = relField.db_column_name || 'id'\n            const foreignCol = relField.relation?.foreign_field || relField.relation_key || relField.foreign_key_column || getPkColumn(allModels, jt) || 'id'\n            if (IDENT.test(jt) && IDENT.test(localCol) && IDENT.test(foreignCol)) {\n              joinSql += ` LEFT JOIN ${Q(refTable)} ON ${qCol(refTable, localCol)} = ${qCol(jt, foreignCol)}`\n              joinedTables.add(refTable)\n              break\n            }\n          }\n        }\n      }\n    })\n\n    return { joinSql, joinedTables }\n  }\n  const { joinSql, joinedTables } = resolveJoinSql(referencedTables, legacyJoins)\n\n  // Rede de segurança: tira de selectStr as colunas de tabelas sem JOIN (evita quebrar o SQL)\n  if (selectStr !== '*') {\n    selectStr = selectStr.split(',').filter(s => {\n      const col = s.trim()\n      if (col === '*') return true\n      if (col.includes('.')) {\n        const t = col.split('.')[0]\n        return joinedTables.has(t) || t === mainTable\n      }\n      return true\n    }).join(', ')\n  }\n\n  // Filtros da tela: só entram os que apontam para uma coluna do próprio widget (tabela principal ou com JOIN).\n  const columnExists = (table: string, column: string) => {\n    const m = allModels.find(x => x.db_table_name === table)\n    const fs = Array.isArray(m?.fields) ? m.fields : Object.values(m?.fields || {})\n    return (fs as any[]).some(f => String(f.db_column_name).toLowerCase() === column.toLowerCase())\n  }\n  const candidateFilters: { col: Col; value: string }[] = []\n  Object.entries(screenFilters).forEach(([key, val]) => {\n    if (!val) return\n    // o nome da coluna entra no SQL entre aspas: só identificadores simples (tabela.coluna) são aceitos\n    if (!FILTER_KEY.test(key)) return\n    const filterTable = key.includes('.') ? key.split('.')[0] : mainTable\n    const filterCol = key.includes('.') ? key.split('.')[1] : key\n    if (!columnExists(filterTable, filterCol)) return\n    candidateFilters.push({ col: { table: filterTable, column: filterCol }, value: String(val) })\n  })\n  const validFilters = candidateFilters.filter(f => joinedTables.has(f.col.table))\n\n  // Tabelas que o widget realmente usa (grupo, valor, fórmula e filtros) → JOINs mínimos\n  const resolveRef = (s: string): Col => s.includes('.') ? { table: s.split('.')[0], column: s.split('.')[1] } : { table: mainTable, column: s }\n  const rawField = widget.field && widget.field !== '*' ? String(widget.field) : ''\n  const aggFormula = rawField && (widget.use_formula || /[*+/()]/.test(rawField)) ? rawField : null\n  let fieldRef: Col | null = null\n  if (rawField && !aggFormula) {\n    const fieldMeta = model?.fields?.find((f: any) => String(f.id) === rawField)\n    fieldRef = resolveRef(fieldMeta?.db_column_name || rawField)\n  }\n  const groupRef = typeof groupCol === 'string' && groupCol ? resolveRef(groupCol) : null\n  const usedTables = new Set<string>([fieldRef?.table, groupRef?.table].filter(Boolean) as string[])\n  if (aggFormula) for (const m of aggFormula.matchAll(/([A-Za-z_][A-Za-z0-9_]*)\\.[A-Za-z_][A-Za-z0-9_]*/g)) usedTables.add(m[1])\n\n  // Filtros do widget (com operador), período, série, métrica derivada\n  const colKind = (table: string, column: string): BiColKind => {\n    const m = allModels.find(x => x.db_table_name === table)\n    const fs = Array.isArray(m?.fields) ? m.fields : Object.values(m?.fields || {})\n    return biFieldKind((fs as any[]).find(x => String(x.db_column_name).toLowerCase() === column.toLowerCase()))\n  }\n  const conditions: BiCondition[] = []\n  ;(widget.conditions || []).forEach(c => {\n    if (!c?.field || !c.op) return\n    const noValue = c.op === 'is_null' || c.op === 'not_null'\n    if (!noValue && (c.value === undefined || c.value === '')) return\n    if (c.op === 'between' && (c.value2 === undefined || c.value2 === '')) return\n    const ref = resolveRef(String(c.field))\n    conditions.push({ col: ref, op: c.op as BiConditionOp, kind: colKind(ref.table, ref.column), value: c.value, value2: c.value2 })\n  })\n  const baseConditions = [...conditions]\n  const periodConditions = (range: PeriodRange): BiCondition[] => {\n    const ref = resolveRef(widget.period_field as string)\n    return [\n      { col: ref, op: 'gte', kind: 'date', value: range.from },\n      { col: ref, op: 'lt', kind: 'date', value: nextDay(range.to) },\n    ]\n  }\n  if (widget.period_field && period) conditions.push(...periodConditions(period))\n  const compare = widget.type === 'kpi' && !widget.group_by && !!widget.compare_previous && !!widget.period_field && !!period\n\n  const seriesRef = widget.series_by && widget.group_by && ['bar', 'line', 'area'].includes(String(widget.type)) ? resolveRef(widget.series_by) : null\n  const divideBy = widget.divide_by?.calc\n    ? { calc: widget.divide_by.calc, field: widget.divide_by.field ? resolveRef(widget.divide_by.field) : null }\n    : null\n  // agrupar por chave estrangeira: mostra o nome do registro relacionado em vez do UUID\n  const groupLabel = groupRef ? resolveFkLabel(allModels, resolvedRelations, groupRef) : null\n  const seriesLabel = seriesRef ? resolveFkLabel(allModels, resolvedRelations, seriesRef) : null\n  if (groupLabel) usedTables.add(groupLabel.label.table)\n  if (seriesLabel) usedTables.add(seriesLabel.label.table)\n  conditions.forEach(c => usedTables.add(c.col.table))\n  if (seriesRef) usedTables.add(seriesRef.table)\n  if (divideBy?.field) usedTables.add(divideBy.field.table)\n\n  // recursos que só o SQL agregado entrega (o caminho de linhas cruas não os implementa)\n  const needsAgg = conditions.length > 0 || !!seriesRef || !!divideBy || widget.calc === 'COUNT_DISTINCT' ||\n    widget.date_granularity === 'week' || widget.date_granularity === 'quarter'\n  let buildReason = ''\n\n  // JOINs mínimos: só as tabelas que o widget usa (grupo, valor e filtros). Os JOINs do caso de uso inteiro\n  // (entregas, projetos, tarefas...) repetiam cada pedido e inflavam SUM/AVG.\n  const filterTables = candidateFilters.map(f => f.col.table)\n  const minimal = resolveJoinSql([...usedTables, ...filterTables].filter(t => t !== mainTable), widget.joins || [])\n  const aggFilters = candidateFilters.filter(f => minimal.joinedTables.has(f.col.table))\n  const minimalOk = [...usedTables].every(t => minimal.joinedTables.has(t))\n\n  // 1) Caminho novo: o banco agrega (GROUP BY / SUM / COUNT) e devolve só as linhas do gráfico\n  if (dialect && !legacy) {\n    if (minimalOk) {\n      const mainPk = getPkColumn(allModels, mainTable) || 'id'\n      const built = buildAggregateQuery({\n        dialect,\n        mainTable,\n        mainPk,\n        joinSql: minimal.joinSql,\n        calc: String(widget.calc || 'COUNT'),\n        formula: aggFormula,\n        field: fieldRef,\n        groupBy: groupRef,\n        granularity: widget.date_granularity,\n        sortBy: widget.sort_by,\n        limitTopN: widget.limit_top_n,\n        filters: aggFilters,\n        conditions,\n        series: seriesRef,\n        divideBy,\n        groupLabel,\n        seriesLabel,\n        maxGroups: input.maxGroups,\n      })\n      if (built.ok) {\n        const limit = input.maxGroups + 100\n        const plan: WidgetPlan = { kind: 'agg', tableName: mainTable, schemaName, sql: built.sql, limit, compare, warnings }\n        if (groupRef) {\n          // agrupado por chave estrangeira o gráfico mostra o nome do registro relacionado: é por ele que se filtra\n          const gcol = groupLabel ? groupLabel.label : groupRef\n          const kind = groupLabel ? 'text' : colKind(gcol.table, gcol.column)\n          plan.group = { field: `${gcol.table}.${gcol.column}`, kind, granularity: kind === 'date' ? widget.date_granularity || undefined : undefined }\n        }\n        // KPI com comparação: segunda consulta, igual à primeira mas no período anterior\n        if (compare && period) {\n          const prevBuilt = buildAggregateQuery({\n            dialect,\n            mainTable,\n            mainPk,\n            joinSql: minimal.joinSql,\n            calc: String(widget.calc || 'COUNT'),\n            formula: aggFormula,\n            field: fieldRef,\n            groupBy: null,\n            filters: aggFilters,\n            conditions: [...baseConditions, ...periodConditions(previousRange(period))],\n            divideBy,\n            maxGroups: input.maxGroups,\n          })\n          if (prevBuilt.ok) plan.prev = { sql: prevBuilt.sql, limit }\n        }\n        return plan\n      }\n      buildReason = built.reason\n      warnings.push(`[BI] consulta agregada não aplicável, usando linhas cruas: ${built.reason}`)\n    } else {\n      buildReason = 'tabela do indicador sem relação com as demais (verifique o caminho de relacionamento)'\n    }\n  }\n\n  if (needsAgg) {\n    const why = input.failureReason ? `consulta falhou no banco: ${input.failureReason}` : buildReason || 'este indicador exige banco PostgreSQL, Oracle, MySQL ou SQL Server'\n    return { ...fail(`Não foi possível calcular: ${why}`), compare }\n  }\n\n  // 2) Caminho de reserva: busca linhas cruas (limitadas) e agrega no cliente\n  // Mesmo aqui, só junta o necessário quando possível (senão JOINs 1:N repetem as linhas)\n  const rawJoinSql = minimalOk ? minimal.joinSql : joinSql\n  const rawJoined = minimalOk ? minimal.joinedTables : joinedTables\n  const rawFilters = minimalOk ? aggFilters : validFilters\n  const whereClause = ['1=1', ...rawFilters.map(f => filterConditionSql(dialect ?? 'other', f))].join(' AND ')\n  let sqlSelect = '*'\n  if (selectStr !== '*') {\n    sqlSelect = selectStr.split(',').map(s => s.trim()).filter(col => {\n      if (col === '*') return true\n      const bare = col.includes('.') ? col.split('.') : [mainTable, col]\n      if (!IDENT.test(bare[0]) || !IDENT.test(bare[1])) return false\n      return !col.includes('.') || rawJoined.has(bare[0]) || bare[0] === mainTable\n    }).map(col => {\n      if (col === '*') return '*'\n      const p = col.includes('.') ? col.split('.') : [mainTable, col]\n      return qCol(p[0], p[1])\n    }).join(', ') || '*'\n  }\n\n  // SQL Server não aceita OFFSET/FETCH sem ORDER BY: aqui usa TOP\n  const top = dialect === 'sqlserver' ? `TOP ${input.rawRowLimit} ` : ''\n  const rawLimit = dialect === 'oracle'\n    ? ` OFFSET 0 ROWS FETCH NEXT ${input.rawRowLimit} ROWS ONLY`\n    : dialect === 'sqlserver' ? '' : ` LIMIT ${input.rawRowLimit}`\n  return {\n    kind: 'raw',\n    tableName: mainTable,\n    schemaName,\n    sql: `SELECT ${top}${sqlSelect} FROM ${Q(mainTable)}${rawJoinSql} WHERE ${whereClause}${rawLimit}`,\n    limit: input.rawRowLimit,\n    compare,\n    warnings,\n  }\n}\n",
  "lib/bi/queryBuilder.ts": "/**\n * Construtor de SQL agregado dos widgets de BI.\n *\n * Em vez de buscar 1000 linhas cruas e agregar no navegador (resultado errado quando a tabela passa disso),\n * o SQL já faz o GROUP BY / SUM / COUNT no banco do cliente e devolve só as linhas do gráfico.\n *\n * Dialetos: PostgreSQL, Oracle, MySQL e SQL Server. No app em execução (túnel), o Agente CLI só executa PostgreSQL e\n * Oracle; MySQL e SQL Server servem ao app exportado, que conversa direto com o banco. Quando o construtor não\n * consegue montar o SQL (ok:false), quem chama usa o caminho antigo (linhas cruas).\n *\n * Multiplicação de linhas (fan-out): quando o valor vem só da tabela principal e há JOINs, o SQL deduplica por\n * chave primária (SELECT DISTINCT pk, grupo, valor) antes de agregar; senão um pedido com 3 itens seria somado 3 vezes.\n * COUNT sem campo conta registros distintos da tabela principal (COUNT DISTINCT pk), não linhas do JOIN.\n */\nimport { parseFormulaAst, type FormulaNode } from './safeFormula'\n\nexport type SqlDialect = 'postgres' | 'oracle' | 'mysql' | 'sqlserver'\nexport const SQL_DIALECTS: SqlDialect[] = ['postgres', 'oracle', 'mysql', 'sqlserver']\n\nexport interface BiColRef { table: string; column: string }\nexport interface BiFilter { col: BiColRef; value: string }\n\nexport type BiConditionOp = 'eq' | 'ne' | 'gt' | 'gte' | 'lt' | 'lte' | 'contains' | 'starts' | 'ends' | 'in' | 'between' | 'is_null' | 'not_null'\nexport type BiColKind = 'text' | 'number' | 'date'\n/** Filtro configurado no widget (com operador), diferente do filtro de tela que é sempre \"contém\". */\nexport interface BiCondition { col: BiColRef; op: BiConditionOp; kind: BiColKind; value?: string; value2?: string }\n/** Métrica usada como denominador de uma métrica derivada (ex.: ticket médio = SUM(valor) ÷ COUNT de pedidos). */\nexport interface BiMetric { calc: string; formula?: string | null; field?: BiColRef | null }\n\nexport interface BuildAggInput {\n  dialect: SqlDialect\n  mainTable: string\n  mainPk: string\n  /** JOINs já resolvidos (ex.: ` LEFT JOIN \"itens_pedido\" ON ...`), ou '' */\n  joinSql: string\n  calc: string\n  /** fórmula (texto) como \"itens_pedido.preco_unitario * itens_pedido.quantidade\" */\n  formula?: string | null\n  /** campo simples do valor */\n  field?: BiColRef | null\n  groupBy?: BiColRef | null\n  granularity?: string\n  sortBy?: string\n  limitTopN?: number\n  filters: BiFilter[]\n  /** filtros do widget e do período global */\n  conditions?: BiCondition[]\n  /** segunda dimensão (série): uma coluna a mais no resultado (bi_series) */\n  series?: BiColRef | null\n  /** métrica derivada: o valor final é (métrica principal) ÷ (esta métrica) */\n  divideBy?: BiMetric | null\n  /**\n   * Quando o agrupamento (ou a série) é uma chave estrangeira, mostra o nome do registro relacionado em vez do UUID:\n   * agrupa pela chave do registro e exibe o rótulo (dois registros com o mesmo nome continuam separados).\n   */\n  groupLabel?: { label: BiColRef; key: BiColRef } | null\n  seriesLabel?: { label: BiColRef; key: BiColRef } | null\n  /** teto de grupos quando não há Top N */\n  maxGroups?: number\n}\n\nexport type BuildAggResult = { ok: true; sql: string; grouped: boolean; series?: boolean } | { ok: false; reason: string }\n\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/\n\nclass Unsupported extends Error {}\n\nfunction ident(id: string): string {\n  if (!IDENT.test(id)) throw new Unsupported(`identificador inválido: ${id}`)\n  return id\n}\n\n/**\n * Tudo o que muda de um banco para outro: aspas, conversão numérica, comparação de texto sem diferenciar\n * maiúsculas, datas, agrupamento por período e limite de linhas.\n */\ninterface Profile {\n  quote(id: string): string\n  /** literal de texto (MySQL escapa a barra invertida; SQL Server usa N'...' para unicode) */\n  lit(v: string): string\n  num(expr: string): string\n  /** `expr LIKE padrão`, sem diferenciar maiúsculas */\n  like(expr: string, pattern: string): string\n  dateLit(v: string): string\n  dayOf(expr: string): string\n  groupDate(ref: string, granularity: string): string | null\n  limit(n: number): string\n  mod(a: string, b: string): string\n  /** arredonda para inteiro (o SQL Server exige o segundo argumento) */\n  round0(expr: string): string\n  /** LEAST (min) ou GREATEST (max) de vários valores */\n  extreme(kind: 'MIN' | 'MAX', args: string[]): string\n  /** converte para número antes de dividir (divisão inteira em alguns bancos) */\n  divNum(expr: string): string\n}\n\nconst baseLit = (v: string) => `'${String(v).replace(/'/g, \"''\").replace(/\\u0000/g, '')}'`\nconst dq = (id: string) => `\"${id}\"`\n\nconst PROFILES: Record<SqlDialect, Profile> = {\n  postgres: {\n    quote: dq,\n    lit: baseLit,\n    num: e => `CAST(${e} AS NUMERIC)`,\n    like: (e, p) => `CAST(${e} AS TEXT) ILIKE ${baseLit(p)}`,\n    dateLit: v => `CAST('${v}' AS TIMESTAMP)`,\n    dayOf: e => `CAST(${e} AS DATE)`,\n    groupDate: (ref, g) => {\n      const ts = `CAST(${ref} AS TIMESTAMP)`\n      const fmt = { day: 'YYYY-MM-DD', month: 'YYYY-MM', year: 'YYYY' }[g]\n      if (fmt) return `TO_CHAR(${ts}, '${fmt}')`\n      // semana e trimestre montados com || para não depender de literais entre aspas dentro do formato\n      if (g === 'week') return `(TO_CHAR(${ts}, 'IYYY') || '-S' || TO_CHAR(${ts}, 'IW'))`\n      if (g === 'quarter') return `(TO_CHAR(${ts}, 'YYYY') || '-T' || TO_CHAR(${ts}, 'Q'))`\n      return null\n    },\n    limit: n => `LIMIT ${n}`,\n    mod: (a, b) => `MOD(${a}, NULLIF(${b}, 0))`,\n    round0: e => `ROUND(${e})`,\n    extreme: (k, a) => `${k === 'MIN' ? 'LEAST' : 'GREATEST'}(${a.join(', ')})`,\n    divNum: e => `CAST(${e} AS NUMERIC)`,\n  },\n  oracle: {\n    quote: dq,\n    lit: baseLit,\n    num: e => `TO_NUMBER(${e})`,\n    like: (e, p) => `UPPER(TO_CHAR(${e})) LIKE UPPER(${baseLit(p)})`,\n    dateLit: v => `TO_DATE('${v}', 'YYYY-MM-DD')`,\n    dayOf: e => `TRUNC(${e})`,\n    groupDate: (ref, g) => {\n      const fmt = { day: 'YYYY-MM-DD', month: 'YYYY-MM', year: 'YYYY' }[g]\n      if (fmt) return `TO_CHAR(${ref}, '${fmt}')`\n      if (g === 'week') return `(TO_CHAR(${ref}, 'IYYY') || '-S' || TO_CHAR(${ref}, 'IW'))`\n      if (g === 'quarter') return `(TO_CHAR(${ref}, 'YYYY') || '-T' || TO_CHAR(${ref}, 'Q'))`\n      return null\n    },\n    limit: n => `OFFSET 0 ROWS FETCH NEXT ${n} ROWS ONLY`,\n    mod: (a, b) => `MOD(${a}, NULLIF(${b}, 0))`,\n    round0: e => `ROUND(${e})`,\n    extreme: (k, a) => `${k === 'MIN' ? 'LEAST' : 'GREATEST'}(${a.join(', ')})`,\n    divNum: e => e,\n  },\n  mysql: {\n    quote: id => `\\`${id}\\``,\n    // no MySQL a barra invertida escapa o caractere seguinte: sem dobrá-la, um valor terminado em \\ quebraria o literal\n    lit: v => `'${String(v).replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\").replace(/\\u0000/g, '')}'`,\n    num: e => `CAST(${e} AS DECIMAL(38,10))`,\n    like: (e, p) => `LOWER(CAST(${e} AS CHAR)) LIKE LOWER(${PROFILES.mysql.lit(p)})`,\n    dateLit: v => `CAST('${v}' AS DATETIME)`,\n    dayOf: e => `CAST(${e} AS DATE)`,\n    groupDate: (ref, g) => {\n      const fmt = { day: '%Y-%m-%d', month: '%Y-%m', year: '%Y' }[g]\n      if (fmt) return `DATE_FORMAT(${ref}, '${fmt}')`\n      if (g === 'week') return `CONCAT(LEFT(YEARWEEK(${ref}, 3), 4), '-S', SUBSTRING(YEARWEEK(${ref}, 3), 5, 2))`\n      if (g === 'quarter') return `CONCAT(YEAR(${ref}), '-T', QUARTER(${ref}))`\n      return null\n    },\n    limit: n => `LIMIT ${n}`,\n    mod: (a, b) => `MOD(${a}, NULLIF(${b}, 0))`,\n    round0: e => `ROUND(${e})`,\n    extreme: (k, a) => `${k === 'MIN' ? 'LEAST' : 'GREATEST'}(${a.join(', ')})`,\n    divNum: e => `CAST(${e} AS DECIMAL(38,10))`,\n  },\n  sqlserver: {\n    quote: id => `[${id}]`,\n    lit: v => `N'${String(v).replace(/'/g, \"''\").replace(/\\u0000/g, '')}'`,\n    num: e => `CAST(${e} AS DECIMAL(38,10))`,\n    like: (e, p) => `UPPER(CAST(${e} AS NVARCHAR(4000))) LIKE UPPER(${PROFILES.sqlserver.lit(p)})`,\n    dateLit: v => `CAST('${v}' AS DATETIME2)`,\n    dayOf: e => `CAST(${e} AS DATE)`,\n    groupDate: (ref, g) => {\n      if (g === 'day') return `CONVERT(VARCHAR(10), ${ref}, 23)`\n      if (g === 'month') return `CONVERT(VARCHAR(7), ${ref}, 23)`\n      if (g === 'year') return `CAST(YEAR(${ref}) AS VARCHAR(4))`\n      // ano ISO da semana: o ano da quinta-feira daquela semana\n      if (g === 'week') return `CONCAT(YEAR(DATEADD(DAY, 26 - DATEPART(ISO_WEEK, ${ref}), ${ref})), '-S', RIGHT(CONCAT('0', DATEPART(ISO_WEEK, ${ref})), 2))`\n      if (g === 'quarter') return `CONCAT(YEAR(${ref}), '-T', DATEPART(QUARTER, ${ref}))`\n      return null\n    },\n    // exige ORDER BY (o construtor sempre ordena quando há agrupamento)\n    limit: n => `OFFSET 0 ROWS FETCH NEXT ${n} ROWS ONLY`,\n    mod: (a, b) => `(${a} % NULLIF(${b}, 0))`,\n    round0: e => `ROUND(${e}, 0)`,\n    // LEAST/GREATEST só existem a partir do SQL Server 2022: CASE funciona em qualquer versão\n    extreme: (k, a) => a.reduce((acc, x) => `(CASE WHEN ${acc} ${k === 'MIN' ? '<' : '>'} ${x} THEN ${acc} ELSE ${x} END)`),\n    divNum: e => `CAST(${e} AS DECIMAL(38,10))`,\n  },\n}\n\n/** Função que coloca um identificador entre aspas no dialeto (usada também para montar os JOINs). */\n/**\n * Oracle guarda os nomes em MAIÚSCULAS e, entre aspas, diferencia a caixa. O Agente CLI converte os identificadores\n * entre aspas antes de executar; o app exportado (sem CLI) faz o mesmo com esta função. Não mexe em texto dentro de\n * literais ('...'), onde \"palavra\" é só um valor.\n */\nexport function oracleUpperIdentifiers(sql: string): string {\n  return sql.replace(/('(?:[^']|'')*')|\"([A-Za-z0-9_]+)\"/g, (m, literal, ident) => (literal ? literal : `\"${String(ident).toUpperCase()}\"`))\n}\n\nexport function quoteFor(dialect: SqlDialect): (id: string) => string {\n  return PROFILES[dialect].quote\n}\n\nfunction refSql(P: Profile, c: BiColRef): string {\n  return `${P.quote(ident(c.table))}.${P.quote(ident(c.column))}`\n}\n\nfunction formulaToSql(node: FormulaNode, P: Profile, mainTable: string, tables: Set<string>): string {\n  switch (node.t) {\n    case 'num': return String(node.v)\n    case 'field': {\n      const table = node.table || mainTable\n      tables.add(table)\n      return P.num(refSql(P, { table, column: node.name }))\n    }\n    case 'neg': return `(-${formulaToSql(node.a, P, mainTable, tables)})`\n    case 'bin': {\n      const a = formulaToSql(node.a, P, mainTable, tables)\n      const b = formulaToSql(node.b, P, mainTable, tables)\n      if (node.op === '/') return `(${a} / NULLIF(${b}, 0))`\n      if (node.op === '%') return P.mod(a, b)\n      return `(${a} ${node.op} ${b})`\n    }\n    case 'fn': {\n      const args = node.args.map(a => formulaToSql(a, P, mainTable, tables))\n      if (node.name === 'ABS' && args.length === 1) return `ABS(${args[0]})`\n      if (node.name === 'ROUND') {\n        const digits = node.args[1]\n        if (args.length === 1) return P.round0(args[0])\n        if (args.length === 2 && digits.t === 'num' && Number.isInteger(digits.v) && digits.v >= 0 && digits.v <= 10) return `ROUND(${args[0]}, ${digits.v})`\n        throw new Unsupported('ROUND com casas dinâmicas')\n      }\n      if (node.name === 'MIN' || node.name === 'MAX') {\n        if (args.length === 1) return args[0]\n        return P.extreme(node.name, args)\n      }\n      throw new Unsupported(`função ${node.name}`)\n    }\n  }\n}\n\nfunction groupExpr(P: Profile, g: BiColRef, granularity?: string): string {\n  const ref = refSql(P, g)\n  if (!granularity) return ref\n  return P.groupDate(ref, granularity) ?? ref\n}\n\n/** Condição de um filtro de tela (contém, sem diferenciar maiúsculas). */\nexport function filterConditionSql(dialect: SqlDialect | 'other', f: BiFilter): string {\n  const P = PROFILES[dialect === 'other' ? 'postgres' : dialect]\n  return P.like(refSql(P, f.col), `%${f.value}%`)\n}\n\nconst DATE_RE = /^\\d{4}-\\d{2}-\\d{2}$/\nconst NUM_RE = /^-?\\d+(\\.\\d+)?$/\n\nfunction valueLiteral(P: Profile, kind: BiColKind, raw: string | undefined): string {\n  const v = String(raw ?? '').trim()\n  if (kind === 'number') {\n    if (!NUM_RE.test(v)) throw new Unsupported(`valor numérico inválido: ${v}`)\n    return v\n  }\n  if (kind === 'date') {\n    if (!DATE_RE.test(v)) throw new Unsupported(`data inválida: ${v}`)\n    return P.dateLit(v)\n  }\n  return P.lit(v)\n}\n\n/** Dia seguinte (YYYY-MM-DD), em UTC para não depender do fuso. Valor inválido deixa passar para a validação do literal. */\nfunction nextDay(v: string | undefined): string {\n  const s = String(v ?? '').trim()\n  if (!DATE_RE.test(s)) return s\n  const [y, m, d] = s.split('-').map(Number)\n  return new Date(Date.UTC(y, m - 1, d + 1)).toISOString().slice(0, 10)\n}\n\nconst CMP: Record<string, string> = { eq: '=', ne: '<>', gt: '>', gte: '>=', lt: '<', lte: '<=' }\n\n/** Condição com operador (filtro do widget ou período). Lança Unsupported se o valor não combina com o tipo da coluna. */\nexport function conditionSql(dialect: SqlDialect, c: BiCondition): string {\n  const P = PROFILES[dialect]\n  const ref = refSql(P, c.col)\n  const val = (v: string | undefined) => valueLiteral(P, c.kind, v)\n  switch (c.op) {\n    case 'is_null': return `${ref} IS NULL`\n    case 'not_null': return `${ref} IS NOT NULL`\n    case 'contains': return P.like(ref, `%${c.value ?? ''}%`)\n    case 'starts': return P.like(ref, `${c.value ?? ''}%`)\n    case 'ends': return P.like(ref, `%${c.value ?? ''}`)\n    case 'in': {\n      const items = String(c.value ?? '').split(',').map(x => x.trim()).filter(Boolean)\n      if (items.length === 0) throw new Unsupported('lista vazia')\n      return `${ref} IN (${items.map(x => val(x)).join(', ')})`\n    }\n    case 'between':\n      // data: o dia final entra inteiro (a coluna pode ter hora): >= início E < dia seguinte ao fim\n      if (c.kind === 'date') return `(${ref} >= ${val(c.value)} AND ${ref} < ${val(nextDay(c.value2))})`\n      return `${ref} BETWEEN ${val(c.value)} AND ${val(c.value2)}`\n    case 'lte':\n      if (c.kind === 'date') return `${ref} < ${val(nextDay(c.value))}`\n      return `${ref} <= ${val(c.value)}`\n    case 'gt':\n      if (c.kind === 'date') return `${ref} >= ${val(nextDay(c.value))}`\n      return `${ref} > ${val(c.value)}`\n    case 'eq':\n    case 'ne':\n      if (c.kind === 'date') return `${P.dayOf(ref)} ${CMP[c.op]} ${val(c.value)}`\n      return `${ref} ${CMP[c.op]} ${val(c.value)}`\n    case 'gte': case 'lt':\n      return `${ref} ${CMP[c.op]} ${val(c.value)}`\n  }\n  throw new Unsupported(`operador ${c.op}`)\n}\n\nexport function whereSql(dialect: SqlDialect, filters: BiFilter[], conditions: BiCondition[] = []): string {\n  return ['1=1', ...filters.map(f => filterConditionSql(dialect, f)), ...conditions.map(c => conditionSql(dialect, c))].join(' AND ')\n}\n\nconst CALCS = ['COUNT', 'COUNT_DISTINCT', 'SUM', 'AVG', 'MIN', 'MAX']\n\n/** SELECT agregado de uma métrica (sem ORDER BY/LIMIT): colunas bi_name, [bi_series], bi_value. */\nfunction metricSelect(input: BuildAggInput, m: BiMetric): { sql: string; grouped: boolean } {\n  const { dialect, mainTable, joinSql } = input\n  const P = PROFILES[dialect]\n  const Q = P.quote\n  const calc = String(m.calc || 'COUNT').toUpperCase()\n  if (!CALCS.includes(calc)) throw new Unsupported(`operação ${calc}`)\n\n  const main = Q(ident(mainTable))\n  const pk = refSql(P, { table: mainTable, column: input.mainPk })\n  const hasJoins = joinSql.trim().length > 0\n  const from = `FROM ${main}${joinSql}`\n  const where = whereSql(dialect, input.filters, input.conditions)\n\n  // valor\n  const valueTables = new Set<string>()\n  let valueSql: string | null = null\n  if (m.formula) {\n    const ast = parseFormulaAst(m.formula)\n    if (!ast) throw new Unsupported('fórmula inválida')\n    valueSql = formulaToSql(ast, P, mainTable, valueTables)\n  } else if (m.field) {\n    valueTables.add(m.field.table)\n    valueSql = P.num(refSql(P, m.field))\n  }\n\n  let aggExpr: string\n  let dedupe = false\n  if (calc === 'COUNT') {\n    // sem campo (ou com campo da tabela principal) conta registros distintos da principal\n    const fieldOnJoined = !m.formula && m.field && m.field.table !== mainTable\n    aggExpr = fieldOnJoined ? `COUNT(${refSql(P, m.field!)})` : hasJoins ? `COUNT(DISTINCT ${pk})` : 'COUNT(*)'\n  } else if (calc === 'COUNT_DISTINCT') {\n    if (m.formula || !m.field) throw new Unsupported('contagem distinta exige um campo')\n    aggExpr = `COUNT(DISTINCT ${refSql(P, m.field)})`\n  } else {\n    if (!valueSql) throw new Unsupported(`${calc} exige um campo ou fórmula`)\n    dedupe = hasJoins && [...valueTables].every(t => t === mainTable)\n    aggExpr = `${calc}(${dedupe ? Q('bi_v') : valueSql})`\n  }\n\n  // dimensões: expressão de exibição primeiro e, para chave estrangeira, a chave do registro depois\n  const gExprs: string[] = !input.groupBy ? [] : input.groupLabel\n    ? [refSql(P, input.groupLabel.label), refSql(P, input.groupLabel.key)]\n    : [groupExpr(P, input.groupBy, input.granularity)]\n  const sExprs: string[] = gExprs.length === 0 || !input.series ? [] : input.seriesLabel\n    ? [refSql(P, input.seriesLabel.label), refSql(P, input.seriesLabel.key)]\n    : [refSql(P, input.series)]\n\n  if (gExprs.length === 0) {\n    const sql = dedupe\n      ? `SELECT ${aggExpr} AS ${Q('bi_value')} FROM (SELECT DISTINCT ${pk} AS ${Q('bi_pk')}, ${valueSql} AS ${Q('bi_v')} ${from} WHERE ${where}) bi_sub`\n      : `SELECT ${aggExpr} AS ${Q('bi_value')} ${from} WHERE ${where}`\n    return { sql, grouped: false }\n  }\n  if (dedupe) {\n    const gAl = ['bi_g', 'bi_gk']\n    const sAl = ['bi_s', 'bi_sk']\n    const inner = [\n      `${pk} AS ${Q('bi_pk')}`,\n      ...gExprs.map((e, i) => `${e} AS ${Q(gAl[i])}`),\n      ...sExprs.map((e, i) => `${e} AS ${Q(sAl[i])}`),\n      `${valueSql} AS ${Q('bi_v')}`,\n    ].join(', ')\n    const cols = sExprs.length ? `${Q('bi_g')} AS ${Q('bi_name')}, ${Q('bi_s')} AS ${Q('bi_series')}` : `${Q('bi_g')} AS ${Q('bi_name')}`\n    const keys = [...gAl.slice(0, gExprs.length), ...sAl.slice(0, sExprs.length)].map(a => Q(a)).join(', ')\n    return { sql: `SELECT ${cols}, ${aggExpr} AS ${Q('bi_value')} FROM (SELECT DISTINCT ${inner} ${from} WHERE ${where}) bi_sub GROUP BY ${keys}`, grouped: true }\n  }\n  const cols = sExprs.length ? `${gExprs[0]} AS ${Q('bi_name')}, ${sExprs[0]} AS ${Q('bi_series')}` : `${gExprs[0]} AS ${Q('bi_name')}`\n  const keys = [...gExprs, ...sExprs].join(', ')\n  return { sql: `SELECT ${cols}, ${aggExpr} AS ${Q('bi_value')} ${from} WHERE ${where} GROUP BY ${keys}`, grouped: true }\n}\n\nexport function buildAggregateQuery(input: BuildAggInput): BuildAggResult {\n  try {\n    const { dialect } = input\n    const P = PROFILES[dialect]\n    if (!P) return { ok: false, reason: `dialeto ${dialect}` }\n    const Q = P.quote\n    const num = metricSelect(input, { calc: input.calc, formula: input.formula, field: input.field })\n    const grouped = num.grouped\n    const hasSeries = grouped && !!input.series\n    const orders: Record<string, string> = {\n      value_desc: `${Q('bi_value')} DESC`,\n      value_asc: `${Q('bi_value')} ASC`,\n      label_asc: `${Q('bi_name')} ASC`,\n      label_desc: `${Q('bi_name')} DESC`,\n    }\n    const order = orders[input.sortBy || 'value_desc'] || orders.value_desc\n    // com série, o corte Top N é feito no navegador (por total do grupo); aqui só o teto de linhas\n    const cap = hasSeries ? Math.max(input.maxGroups ?? 2000, 2000) * 5 : (input.limitTopN && input.limitTopN > 0 ? input.limitTopN : (input.maxGroups ?? 2000))\n    const lim = P.limit(Math.max(1, Math.trunc(cap)))\n\n    if (!input.divideBy) {\n      if (!grouped) return { ok: true, sql: num.sql, grouped: false }\n      return { ok: true, sql: `${num.sql} ORDER BY ${order} ${lim}`, grouped: true, series: hasSeries }\n    }\n\n    // métrica derivada: duas agregações (cada uma com sua própria deduplicação) combinadas por grupo\n    const den = metricSelect(input, input.divideBy)\n    const bv = `${Q('bi_value')}`\n    if (!grouped) {\n      return { ok: true, grouped: false, sql: `SELECT ${P.divNum(`n.${bv}`)} / NULLIF(d.${bv}, 0) AS ${bv} FROM (${num.sql}) n CROSS JOIN (${den.sql}) d` }\n    }\n    const same = (col: string) => `(n.${Q(col)} = d.${Q(col)} OR (n.${Q(col)} IS NULL AND d.${Q(col)} IS NULL))`\n    const on = hasSeries ? `${same('bi_name')} AND ${same('bi_series')}` : same('bi_name')\n    const cols = hasSeries ? `n.${Q('bi_name')} AS ${Q('bi_name')}, n.${Q('bi_series')} AS ${Q('bi_series')}` : `n.${Q('bi_name')} AS ${Q('bi_name')}`\n    return {\n      ok: true, grouped: true, series: hasSeries,\n      sql: `SELECT ${cols}, ${P.divNum(`n.${bv}`)} / NULLIF(d.${bv}, 0) AS ${bv} FROM (${num.sql}) n LEFT JOIN (${den.sql}) d ON ${on} ORDER BY ${order} ${lim}`,\n    }\n  } catch (e: any) {\n    return { ok: false, reason: e?.message || 'não suportado' }\n  }\n}\n",
  "lib/bi/safeFormula.ts": "/**\n * Avaliador seguro das fórmulas dos widgets de BI (ex.: \"itens_pedido.preco_unitario * itens_pedido.quantidade\").\n * Substitui o antigo `new Function('r', 'with(r){...}')`, que executava como JavaScript qualquer texto salvo no layout.\n *\n * Aceita apenas: números, campos (com ou sem prefixo \"tabela.\"), + - * / % , parênteses e as funções ROUND, ABS, MIN, MAX.\n * Qualquer outra coisa (identificadores desconhecidos como função, strings, ponto e vírgula...) invalida a fórmula,\n * que passa a valer 0 em todas as linhas.\n */\n\nexport type FormulaNode =\n  | { t: 'num'; v: number }\n  | { t: 'field'; name: string; table?: string }\n  | { t: 'neg'; a: FormulaNode }\n  | { t: 'bin'; op: string; a: FormulaNode; b: FormulaNode }\n  | { t: 'fn'; name: string; args: FormulaNode[] }\n\ntype Node = FormulaNode\n\nconst FUNCTIONS = new Set(['ROUND', 'ABS', 'MIN', 'MAX'])\n\nfunction tokenize(src: string): string[] | null {\n  const tokens: string[] = []\n  const re = /\\s*(\\d+(?:\\.\\d+)?|[A-Za-z_][A-Za-z0-9_]*(?:\\.[A-Za-z_][A-Za-z0-9_]*)?|[-+*/%(),])/y\n  let pos = 0\n  while (pos < src.length) {\n    if (/^\\s*$/.test(src.slice(pos))) break\n    re.lastIndex = pos\n    const m = re.exec(src)\n    if (!m) return null\n    tokens.push(m[1])\n    pos = re.lastIndex\n  }\n  return tokens\n}\n\nfunction parse(tokens: string[]): Node | null {\n  let i = 0\n  const peek = () => tokens[i]\n  const next = () => tokens[i++]\n\n  const expr = (): Node | null => {\n    let left = term()\n    while (left && (peek() === '+' || peek() === '-')) {\n      const op = next()\n      const right = term()\n      if (!right) return null\n      left = { t: 'bin', op, a: left, b: right }\n    }\n    return left\n  }\n  const term = (): Node | null => {\n    let left = unary()\n    while (left && (peek() === '*' || peek() === '/' || peek() === '%')) {\n      const op = next()\n      const right = unary()\n      if (!right) return null\n      left = { t: 'bin', op, a: left, b: right }\n    }\n    return left\n  }\n  const unary = (): Node | null => {\n    if (peek() === '-') { next(); const a = unary(); return a ? { t: 'neg', a } : null }\n    if (peek() === '+') { next(); return unary() }\n    return primary()\n  }\n  const primary = (): Node | null => {\n    const tok = next()\n    if (tok === undefined) return null\n    if (tok === '(') {\n      const e = expr()\n      if (!e || next() !== ')') return null\n      return e\n    }\n    if (/^\\d/.test(tok)) return { t: 'num', v: Number(tok) }\n    if (/^[A-Za-z_]/.test(tok)) {\n      if (peek() === '(') {\n        const name = tok.toUpperCase()\n        if (!FUNCTIONS.has(name)) return null\n        next()\n        const args: Node[] = []\n        if (peek() !== ')') {\n          while (true) {\n            const a = expr()\n            if (!a) return null\n            args.push(a)\n            if (peek() === ',') { next(); continue }\n            break\n          }\n        }\n        if (next() !== ')') return null\n        return { t: 'fn', name, args }\n      }\n      // campo: o prefixo \"tabela.\" é descartado (as linhas vêm com o nome simples da coluna)\n      return tok.includes('.')\n        ? { t: 'field', table: tok.split('.')[0], name: tok.split('.').pop()! }\n        : { t: 'field', name: tok }\n    }\n    return null\n  }\n\n  const root = expr()\n  return root && i === tokens.length ? root : null\n}\n\nfunction lookup(row: any, name: string): number {\n  let raw = row?.[name]\n  if (raw === undefined && row) {\n    const low = name.toLowerCase()\n    const key = Object.keys(row).find(k => k.toLowerCase() === low)\n    if (key) raw = row[key]\n  }\n  const n = Number(raw)\n  return raw === null || raw === undefined || raw === '' || !Number.isFinite(n) ? 0 : n\n}\n\nfunction evaluate(node: Node, row: any): number {\n  switch (node.t) {\n    case 'num': return node.v\n    case 'field': return lookup(row, node.name)\n    case 'neg': return -evaluate(node.a, row)\n    case 'bin': {\n      const a = evaluate(node.a, row)\n      const b = evaluate(node.b, row)\n      switch (node.op) {\n        case '+': return a + b\n        case '-': return a - b\n        case '*': return a * b\n        case '/': return b === 0 ? 0 : a / b\n        case '%': return b === 0 ? 0 : a % b\n      }\n      return 0\n    }\n    case 'fn': {\n      const args = node.args.map(a => evaluate(a, row))\n      switch (node.name) {\n        case 'ROUND': return args.length > 1 ? Number(args[0].toFixed(Math.max(0, Math.min(10, Math.trunc(args[1]))))) : Math.round(args[0] ?? 0)\n        case 'ABS': return Math.abs(args[0] ?? 0)\n        case 'MIN': return args.length ? Math.min(...args) : 0\n        case 'MAX': return args.length ? Math.max(...args) : 0\n      }\n      return 0\n    }\n  }\n}\n\n/** Compila a fórmula uma vez; a função devolvida calcula o valor de cada linha (sempre um número finito). */\nexport function compileFormula(formula: string): (row: any) => number {\n  const tokens = tokenize(formula || '')\n  const ast = tokens ? parse(tokens) : null\n  if (!ast) return () => 0\n  return (row: any) => {\n    const v = evaluate(ast, row)\n    return Number.isFinite(v) ? v : 0\n  }\n}\n\n/** Árvore da fórmula (para gerar SQL). null se a fórmula for inválida. */\nexport function parseFormulaAst(formula: string): FormulaNode | null {\n  const tokens = tokenize(formula || '')\n  return tokens ? parse(tokens) : null\n}\n",
  "lib/bi/fkLabel.ts": "/**\n * Agrupar por uma chave estrangeira (ex.: pedidos.cliente_id) mostrava o UUID no gráfico.\n * Aqui descobrimos, pelas relações do projeto, qual é o registro relacionado e qual coluna o descreve\n * (o primeiro campo de texto visível que não seja chave primária nem chave estrangeira, como no restante do produto).\n */\nimport type { BiColRef } from './queryBuilder'\n\nexport interface FkRelation { from_table: string; from_field: string; to_table: string; to_field: string }\n\nconst TEXT_TYPE = /(char|text|string|citext)/i\nconst eq = (a?: string | null, b?: string | null) => String(a ?? '').toLowerCase() === String(b ?? '').toLowerCase()\n\n/** Coluna que descreve o registro de uma tabela, ou null se não houver campo de texto adequado. */\nexport function pickLabelColumn(model: any, relations: FkRelation[]): string | null {\n  if (!model) return null\n  const table = model.db_table_name\n  const fkColumns = new Set(relations.filter(r => eq(r.from_table, table)).map(r => String(r.from_field).toLowerCase()))\n  const fields: any[] = (Array.isArray(model.fields) ? model.fields : Object.values(model.fields || {}))\n    .slice()\n    .sort((a: any, b: any) => (a.order_index ?? 0) - (b.order_index ?? 0))\n  const f = fields.find(x =>\n    !x.is_primary_key &&\n    !fkColumns.has(String(x.db_column_name).toLowerCase()) &&\n    x.is_visible_in_list !== false &&\n    TEXT_TYPE.test(String(x.db_data_type || x.data_type || '')),\n  )\n  return f?.db_column_name ?? null\n}\n\n/** Se `ref` é uma chave estrangeira com campo descritivo no registro relacionado: { label, key }; senão null. */\nexport function resolveFkLabel(models: any[], relations: FkRelation[], ref: BiColRef): { label: BiColRef; key: BiColRef } | null {\n  const rel = relations.find(r => eq(r.from_table, ref.table) && eq(r.from_field, ref.column) && r.to_table && r.to_field)\n  if (!rel) return null\n  const target = models.find(m => eq(m.db_table_name, rel.to_table))\n  const labelCol = pickLabelColumn(target, relations)\n  if (!labelCol) return null\n  return { label: { table: rel.to_table, column: labelCol }, key: { table: rel.to_table, column: rel.to_field } }\n}\n",
  "lib/bi/columnKind.ts": "/**\n * Classifica uma coluna (pelo tipo do banco) em texto, número ou data para os filtros do BI.\n * O tipo vem de `fields.data_type` (PostgreSQL: \"timestamp with time zone\", \"integer\"; Oracle: \"NUMBER\", \"DATE\", \"VARCHAR2\").\n */\nimport type { BiColKind } from './queryBuilder'\n\nconst NUMERIC = /^(int[248]?|integer|smallint|bigint|serial\\d?|bigserial|smallserial|numeric|decimal|real|double|float\\d?|number|money|binary_float|binary_double)(\\b|\\()/\nconst DATE = /^(date|time|timestamp|datetime|smalldatetime)/\n\nexport function biColumnKind(dataType?: string | null): BiColKind {\n  const t = String(dataType ?? '').trim().toLowerCase()\n  if (!t) return 'text'\n  if (DATE.test(t)) return 'date'\n  if (NUMERIC.test(t)) return 'number'\n  return 'text'\n}\n\n/** Tipo do campo a partir do cadastro do campo (aceita data_type ou db_data_type). */\nexport function biFieldKind(field: any): BiColKind {\n  return biColumnKind(field?.db_data_type || field?.data_type)\n}\n",
  "lib/bi/period.ts": "/**\n * Períodos do BI (filtro do painel, período fixo e seletor próprio de cada widget).\n * Datas em YYYY-MM-DD; o fim é inclusivo (o SQL usa \"< dia seguinte\").\n */\n\nexport interface PeriodRange { from: string; to: string }\n\nexport const PERIOD_PRESETS: { id: string; label: string }[] = [\n  { id: 'all', label: 'Tudo' },\n  { id: '7d', label: '7 dias' },\n  { id: '30d', label: '30 dias' },\n  { id: '90d', label: '90 dias' },\n  { id: 'month', label: 'Mês atual' },\n  { id: 'prev_month', label: 'Mês anterior' },\n  { id: '12m', label: '12 meses' },\n  { id: 'year', label: 'Ano atual' },\n  { id: 'prev_year', label: 'Ano anterior' },\n]\n\nconst DATE_RE = /^\\d{4}-\\d{2}-\\d{2}$/\n\nfunction iso(d: Date): string {\n  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`\n}\n\n/** Intervalo de um período pré-definido (ou 'custom' com datas). 'all' ou dados incompletos → null (sem filtro). */\nexport function resolvePeriod(preset: string | undefined, custom?: { from?: string; to?: string }, today: Date = new Date()): PeriodRange | null {\n  const y = today.getFullYear()\n  const m = today.getMonth()\n  const back = (days: number) => { const d = new Date(today); d.setDate(d.getDate() - days); return iso(d) }\n  switch (preset) {\n    case '7d': return { from: back(6), to: iso(today) }\n    case '30d': return { from: back(29), to: iso(today) }\n    case '90d': return { from: back(89), to: iso(today) }\n    case 'month': return { from: iso(new Date(y, m, 1)), to: iso(today) }\n    case 'prev_month': return { from: iso(new Date(y, m - 1, 1)), to: iso(new Date(y, m, 0)) }\n    case '12m': return { from: iso(new Date(y, m - 11, 1)), to: iso(today) }\n    case 'year': return { from: `${y}-01-01`, to: iso(today) }\n    case 'prev_year': return { from: `${y - 1}-01-01`, to: `${y - 1}-12-31` }\n    case 'custom': {\n      const f = custom?.from ?? ''\n      const t = custom?.to ?? ''\n      return DATE_RE.test(f) && DATE_RE.test(t) && f <= t ? { from: f, to: t } : null\n    }\n    default: return null\n  }\n}\n\n/** \"2026-03-31\" → \"31/03/2026\" */\nexport function formatPeriodDay(d: string): string {\n  return d.split('-').reverse().join('/')\n}\n\n/**\n * Período de comparação (\"vs período anterior\"):\n *  - do dia 1 até um dia do mesmo mês → mesmo trecho do mês anterior (limitado ao tamanho dele);\n *  - 1º de janeiro até uma data do mesmo ano → mesmo trecho do ano anterior;\n *  - qualquer outro → o mesmo número de dias imediatamente antes.\n */\nexport function previousRange(r: PeriodRange): PeriodRange {\n  const [fy, fm, fd] = r.from.split('-').map(Number)\n  const [ty, tm, td] = r.to.split('-').map(Number)\n  if (fd === 1 && fy === ty && fm === tm) {\n    const pm = new Date(fy, fm - 2, 1)\n    const last = new Date(pm.getFullYear(), pm.getMonth() + 1, 0).getDate()\n    return { from: iso(pm), to: iso(new Date(pm.getFullYear(), pm.getMonth(), Math.min(td, last))) }\n  }\n  if (fm === 1 && fd === 1 && fy === ty) {\n    const last = new Date(fy - 1, tm, 0).getDate()\n    return { from: `${fy - 1}-01-01`, to: iso(new Date(fy - 1, tm - 1, Math.min(td, last))) }\n  }\n  const from = new Date(fy, fm - 1, fd)\n  const to = new Date(ty, tm - 1, td)\n  const days = Math.round((to.getTime() - from.getTime()) / 86400000) + 1\n  const prevTo = new Date(from)\n  prevTo.setDate(prevTo.getDate() - 1)\n  const prevFrom = new Date(prevTo)\n  prevFrom.setDate(prevFrom.getDate() - (days - 1))\n  return { from: iso(prevFrom), to: iso(prevTo) }\n}\n\n/** Dia seguinte (YYYY-MM-DD), em UTC para não depender do fuso. */\nexport function nextDay(d: string): string {\n  const [y, m, dd] = d.split('-').map(Number)\n  return new Date(Date.UTC(y, m - 1, dd + 1)).toISOString().slice(0, 10)\n}\n\nexport interface PeriodChoice { preset: string; from?: string; to?: string }\n\n/** Modo efetivo: \"segue o grupo\" só vale se o widget realmente está num grupo existente; senão ele segue o painel. */\nexport function effectivePeriodMode(\n  w: { period_mode?: string; group_id?: string },\n  groupIds: string[],\n): 'panel' | 'fixed' | 'own' | 'group' {\n  const mode = (w.period_mode || 'panel') as 'panel' | 'fixed' | 'own' | 'group'\n  if (mode === 'group' && !(w.group_id && groupIds.includes(w.group_id))) return 'panel'\n  return mode\n}\n\n/**\n * Período que vale para um widget: da barra do painel, fixo, do seletor do próprio card ou da barra do grupo.\n * Sem `period_field` o widget não recebe filtro de período.\n */\nexport function resolveWidgetPeriod(\n  w: { id: string; period_field?: string; period_mode?: string; period_fixed?: string; group_id?: string },\n  ctx: { panel: PeriodRange | null; groupIds: string[]; groupPeriods?: Record<string, PeriodChoice>; ownPeriods?: Record<string, PeriodChoice>; today?: Date },\n): PeriodRange | null {\n  if (!w.period_field) return null\n  const mode = effectivePeriodMode(w, ctx.groupIds)\n  if (mode === 'fixed') return resolvePeriod(w.period_fixed || 'month', undefined, ctx.today)\n  if (mode === 'group') {\n    const gp = ctx.groupPeriods?.[w.group_id as string]\n    return gp ? resolvePeriod(gp.preset, { from: gp.from, to: gp.to }, ctx.today) : null\n  }\n  if (mode === 'own') {\n    const o = ctx.ownPeriods?.[w.id]\n    return o ? resolvePeriod(o.preset, { from: o.from, to: o.to }, ctx.today) : null\n  }\n  return ctx.panel\n}\n",
  "lib/bi/widget.ts": "/**\n * Esquema ÚNICO do widget de BI, no formato em que é gravado (analytics_config.widgets).\n *\n * Antes havia três descrições que divergiam: a do painel em execução (AnalyticsDashboard), a do Studio (types.ts)\n * e a do gerador do app exportado (ast.ts, em camelCase). Agora todas usam estes tipos; o gerador guarda o widget\n * original em `spec` e cada recurso novo é escrito uma vez só, aqui.\n */\nimport type { BiGroup } from './groups'\nimport type { RlsRule } from './access'\n\nexport type BiWidgetType = 'kpi' | 'bar' | 'pie' | 'line' | 'area' | 'gauge'\nexport type BiWidgetCalc = 'COUNT' | 'COUNT_DISTINCT' | 'SUM' | 'AVG' | 'MIN' | 'MAX'\nexport type BiWidgetWidth = 'full' | 'half' | 'third' | 'quarter'\nexport type BiPeriodMode = 'panel' | 'fixed' | 'own' | 'group'\n\n/** Filtro do widget com operador (campo = \"tabela.coluna\"). */\nexport interface BiWidgetCondition { field: string; op: string; value?: string; value2?: string }\n\nexport interface BiWidget {\n  id: string\n  title?: string\n  type: BiWidgetType | string\n  model_id?: string\n  model_name?: string\n  /** campo do valor (\"tabela.coluna\"), fórmula (quando use_formula) ou vazio = toda a tabela */\n  field?: string\n  field_id?: string\n  calc?: BiWidgetCalc | string\n  /** agrupar por (\"tabela.coluna\") */\n  group_by?: string\n  width?: BiWidgetWidth | string\n  /** JOINs configurados manualmente (legado) */\n  joins?: any[]\n\n  // medidor\n  gauge_min?: number\n  gauge_max?: number\n  gauge_target?: number\n  gauge_start?: number\n  gauge_end?: number\n\n  // valor e agrupamento\n  use_formula?: boolean\n  formula_tokens?: any[]\n  date_granularity?: 'day' | 'week' | 'month' | 'quarter' | 'year' | string\n  sort_by?: 'value_desc' | 'value_asc' | 'label_asc' | 'label_desc' | string\n  limit_top_n?: number\n\n  // aparência\n  format?: string\n  decimals?: number\n  currency?: string\n  color?: string\n  show_labels?: boolean\n  highlight_max?: boolean\n  orientation?: 'vertical' | 'horizontal' | string\n  stacked?: boolean\n\n  // Fase 2\n  conditions?: BiWidgetCondition[]\n  /** segunda dimensão (série) para barras, linhas e área */\n  series_by?: string\n  /** métrica derivada: valor = (calc/field) ÷ (divide_by.calc/divide_by.field) */\n  divide_by?: { calc: string; field?: string }\n  /** campo de data que recebe o filtro de período */\n  period_field?: string\n  period_mode?: BiPeriodMode\n  period_fixed?: string\n  /** agrupamento a que o widget pertence (id em analytics_config.groups) */\n  group_id?: string\n  /** caminho de relação escolhido por tabela (assinatura do caminho); sem escolha vale o mais curto */\n  relation_paths?: Record<string, string>\n  // Fase 4 — interações\n  /** clicar numa barra/fatia deste gráfico filtra os widgets que respondem ao filtro cruzado */\n  cross_source?: boolean\n  /** este widget responde aos filtros cruzados dos outros gráficos */\n  cross_target?: boolean\n  /** clicar numa barra/fatia permite \"detalhar\": próximo nível de data ou a dimensão `drill_by` */\n  drill_detail?: boolean\n  /** dimensão do próximo nível (TABELA.COLUNA) quando o agrupamento não é uma data */\n  drill_by?: string\n  /** clicar numa barra/fatia permite ver os registros que compõem o número */\n  drill_records?: boolean\n  /** KPI sem agrupamento: variação contra o período anterior */\n  compare_previous?: boolean\n  compare_invert?: boolean\n}\n\n/** Widget já normalizado para exibir (o painel exige estes campos preenchidos). */\nexport type RuntimeBiWidget = BiWidget & {\n  title: string\n  model_id: string\n  field: string\n  calc: BiWidgetCalc | string\n  width: BiWidgetWidth | string\n}\n\nexport interface BiAnalyticsConfig {\n  widgets: BiWidget[]\n  groups?: BiGroup[]\n  allow_runtime_edit?: boolean\n  /** campo de data do filtro global de período do app exportado (ex.: 'data_pedido') */\n  date_filter_field?: string\n  // Fase 5\n  /** acesso por linha: cada regra limita as linhas de acordo com o usuário logado */\n  rls?: RlsRule[]\n  /** guarda o resultado de cada consulta por este tempo (0 = sem cache) */\n  cache_seconds?: number\n  /** atualiza o painel sozinho a cada tanto tempo (0 = desligado) */\n  refresh_seconds?: number\n  /** tempo máximo de espera de cada indicador */\n  timeout_seconds?: number\n}\n",
  "lib/bi/groups.ts": "/**\n * Agrupamentos de widgets do painel de BI.\n *\n * Modelo: `analytics_config.groups = [{ id, title }]` (a ordem do array é a ordem dos grupos na tela) e cada\n * widget aponta para o grupo por `group_id`. Widgets sem grupo (ou com grupo que não existe mais) ficam soltos, no topo.\n * A ordem do array `widgets` acompanha a tela: soltos primeiro, depois os grupos na ordem deles.\n */\n\nexport interface BiGroup { id: string; title: string }\ninterface W { id: string; group_id?: string | null }\n\nexport interface BiSection<T extends W> { group: BiGroup | null; widgets: T[] }\n\nexport function newGroupId(): string {\n  return 'grp_' + Math.random().toString(36).slice(2, 9)\n}\n\n/** Seções na ordem da tela: [soltos, ...grupos]. A seção dos soltos sempre existe (pode estar vazia). */\nexport function sectionsOf<T extends W>(widgets: T[], groups: BiGroup[]): BiSection<T>[] {\n  const known = new Set(groups.map(g => g.id))\n  const loose = widgets.filter(w => !w.group_id || !known.has(w.group_id))\n  return [\n    { group: null, widgets: loose },\n    ...groups.map(g => ({ group: g, widgets: widgets.filter(w => w.group_id === g.id) })),\n  ]\n}\n\nexport function flatten<T extends W>(sections: BiSection<T>[]): T[] {\n  return sections.flatMap(s => s.widgets)\n}\n\n/**\n * Move um widget para um grupo (null = solto) na posição `toIndex` da lista de destino\n * (o índice vale depois de tirar o widget da origem; 'end' = no fim). Devolve o array de widgets já na ordem da tela.\n */\nexport function moveWidget<T extends W>(widgets: T[], groups: BiGroup[], widgetId: string, toGroupId: string | null, toIndex: number | 'end'): T[] {\n  const moving = widgets.find(w => w.id === widgetId)\n  if (!moving) return widgets\n  const target = toGroupId && groups.some(g => g.id === toGroupId) ? toGroupId : null\n  const sections = sectionsOf(widgets.filter(w => w.id !== widgetId), groups)\n  const dest = sections.find(s => (s.group?.id ?? null) === target)\n  if (!dest) return widgets\n  const updated = { ...moving, group_id: target ?? undefined } as T\n  const at = toIndex === 'end' ? dest.widgets.length : Math.max(0, Math.min(toIndex, dest.widgets.length))\n  dest.widgets.splice(at, 0, updated)\n  return flatten(sections)\n}\n\n/** Move um grupo para outra posição na lista de grupos. */\nexport function moveGroup(groups: BiGroup[], groupId: string, toIndex: number): BiGroup[] {\n  const from = groups.findIndex(g => g.id === groupId)\n  if (from < 0) return groups\n  const next = [...groups]\n  const [g] = next.splice(from, 1)\n  next.splice(Math.max(0, Math.min(toIndex, next.length)), 0, g)\n  return next\n}\n\n/** Cria um grupo; o título pode ficar vazio (a tela mostra uma dica até o usuário digitar). */\nexport function addGroup(groups: BiGroup[], title: string, id: string = newGroupId()): BiGroup[] {\n  return [...groups, { id, title: title.trim() }]\n}\n\n/** Renomeia; um nome em branco é ignorado (o grupo mantém o nome atual). */\nexport function renameGroup(groups: BiGroup[], id: string, title: string): BiGroup[] {\n  const t = title.trim()\n  if (!t) return groups\n  return groups.map(g => (g.id === id ? { ...g, title: t } : g))\n}\n\n/** Remove o grupo; os widgets dele ficam soltos (nada é apagado). */\nexport function removeGroup<T extends W>(groups: BiGroup[], widgets: T[], id: string): { groups: BiGroup[]; widgets: T[] } {\n  const nextGroups = groups.filter(g => g.id !== id)\n  const nextWidgets = widgets.map(w => (w.group_id === id ? { ...w, group_id: undefined } : w)) as T[]\n  return { groups: nextGroups, widgets: flatten(sectionsOf(nextWidgets, nextGroups)) }\n}\n\n/** Normaliza o array de widgets para a ordem da tela (útil depois de mexer em group_id). */\nexport function normalizeOrder<T extends W>(widgets: T[], groups: BiGroup[]): T[] {\n  return flatten(sectionsOf(widgets, groups))\n}\n\n/** Texto de exibição de um grupo (um grupo recém-criado ainda não tem título). */\nexport function groupLabel(g: BiGroup): string {\n  return g.title || 'Grupo sem nome'\n}\n",
  "lib/bi/scaleLayout.ts": "/**\n * Escala do painel de BI (botões Pequeno / Médio / Normal / Grande / Extra Grande).\n *\n * Antes a escala era só um zoom do CSS: o painel continuava com 3 cards por linha, apenas menores. Agora cada tamanho\n * muda a DENSIDADE: quantos cards cabem por linha (colunas de uma grade de 12), a altura mínima, a altura dos gráficos\n * e o zoom do texto — como na galeria de Produtos (Pequeno = mais cards e mais compactos, para quem quer economizar\n * tela e abrir o card na lupa quando precisar).\n */\n\nexport type ScaleKey = 'small' | 'medium' | 'normal' | 'large' | 'xl'\nexport type WidthKey = 'full' | 'half' | 'third' | 'quarter'\n\nexport interface ScalePreset {\n  key: ScaleKey\n  label: string\n  /** zoom do texto e dos espaçamentos */\n  zoom: number\n  /** colunas (de 12) ocupadas por cada largura de widget */\n  spans: Record<WidthKey, number>\n  /** altura dos gráficos dentro do card */\n  chartHeight: number\n}\n\nexport const SCALE_PRESETS: ScalePreset[] = [\n  { key: 'small', label: 'Pequeno', zoom: 0.9, spans: { full: 6, half: 3, third: 2, quarter: 2 }, chartHeight: 170 },\n  { key: 'medium', label: 'Médio', zoom: 0.95, spans: { full: 12, half: 4, third: 3, quarter: 3 }, chartHeight: 210 },\n  { key: 'normal', label: 'Normal', zoom: 1, spans: { full: 12, half: 6, third: 4, quarter: 3 }, chartHeight: 250 },\n  { key: 'large', label: 'Grande', zoom: 1.05, spans: { full: 12, half: 12, third: 6, quarter: 4 }, chartHeight: 300 },\n  { key: 'xl', label: 'Extra Grande', zoom: 1.2, spans: { full: 12, half: 12, third: 12, quarter: 6 }, chartHeight: 380 },\n]\n\nexport function presetOf(key: ScaleKey | string | undefined): ScalePreset {\n  return SCALE_PRESETS.find(p => p.key === key) || SCALE_PRESETS.find(p => p.key === 'normal')!\n}\n\nexport function widthKey(width: string | undefined): WidthKey {\n  return width === 'full' || width === 'half' || width === 'third' || width === 'quarter' ? width : 'third'\n}\n\n/** Colunas (de 12) que o widget ocupa na escala escolhida. */\nexport function spanFor(width: string | undefined, key: ScaleKey | string | undefined): number {\n  return presetOf(key).spans[widthKey(width)]\n}\n\n/** Largura \"efetiva\" do widget na escala (a fonte do KPI acompanha o espaço real que ele tem). */\nexport function widthOfSpan(span: number): WidthKey {\n  if (span >= 12) return 'full'\n  if (span >= 6) return 'half'\n  if (span >= 4) return 'third'\n  return 'quarter'\n}\n",
  "lib/bi/interaction.ts": "/**\n * Interações do painel de BI (Fase 4): filtro cruzado e drill-down.\n *\n * Tudo aqui é puro (sem React, sem SQL): transforma o clique do usuário numa lista de condições que o planejador\n * (widgetPlan) já sabe executar. O painel em execução e o app exportado usam estas mesmas funções.\n */\nimport type { BiWidget, BiWidgetCondition } from './widget'\n\nexport type GroupKind = 'text' | 'number' | 'date'\n\n/** Como o gráfico está agrupado (informado pelo planejador): campo a filtrar, tipo e granularidade de data. */\nexport interface GroupInfo { field: string; kind: GroupKind; granularity?: string }\n\nconst DATE_RE = /^\\d{4}-\\d{2}-\\d{2}/\nconst pad = (n: number) => String(n).padStart(2, '0')\nconst iso = (y: number, m: number, d: number) => `${y}-${pad(m)}-${pad(d)}`\n\n/** Último dia do mês (m de 1 a 12). */\nfunction lastDayOf(y: number, m: number): number {\n  return new Date(Date.UTC(y, m, 0)).getUTCDate()\n}\n\n/** Segunda-feira da semana ISO (ano ISO + número da semana). */\nfunction isoWeekMonday(y: number, w: number): Date {\n  const jan4 = new Date(Date.UTC(y, 0, 4))\n  const dow = jan4.getUTCDay() || 7\n  const mondayW1 = new Date(Date.UTC(y, 0, 4 - (dow - 1)))\n  return new Date(mondayW1.getTime() + (w - 1) * 7 * 86400000)\n}\n\n/** Intervalo [de, até] (datas inclusivas, YYYY-MM-DD) que o rótulo do grupo representa, ou null se não reconhecido. */\nexport function bucketRange(granularity: string, name: string): { from: string; to: string } | null {\n  const n = name.trim()\n  let m: RegExpMatchArray | null\n  switch (granularity) {\n    case 'day':\n      return /^\\d{4}-\\d{2}-\\d{2}$/.test(n) ? { from: n, to: n } : null\n    case 'month':\n      m = n.match(/^(\\d{4})-(\\d{2})$/)\n      return m ? { from: iso(+m[1], +m[2], 1), to: iso(+m[1], +m[2], lastDayOf(+m[1], +m[2])) } : null\n    case 'year':\n      m = n.match(/^(\\d{4})$/)\n      return m ? { from: iso(+m[1], 1, 1), to: iso(+m[1], 12, 31) } : null\n    case 'quarter': {\n      m = n.match(/^(\\d{4})-T([1-4])$/)\n      if (!m) return null\n      const startMonth = (+m[2] - 1) * 3 + 1\n      return { from: iso(+m[1], startMonth, 1), to: iso(+m[1], startMonth + 2, lastDayOf(+m[1], startMonth + 2)) }\n    }\n    case 'week': {\n      m = n.match(/^(\\d{4})-S(\\d{1,2})$/)\n      if (!m) return null\n      const mon = isoWeekMonday(+m[1], +m[2])\n      const sun = new Date(mon.getTime() + 6 * 86400000)\n      return { from: mon.toISOString().slice(0, 10), to: sun.toISOString().slice(0, 10) }\n    }\n  }\n  return null\n}\n\n/** Condições que selecionam o grupo clicado (a barra/fatia de nome `name`). */\nexport function bucketConditions(group: GroupInfo, name: string): BiWidgetCondition[] {\n  const field = group.field\n  if (name === 'N/A') return [{ field, op: 'is_null' }]\n  if (group.kind === 'date') {\n    if (group.granularity) {\n      const r = bucketRange(group.granularity, name)\n      return r ? [{ field, op: 'between', value: r.from, value2: r.to }] : []\n    }\n    // sem granularidade o grupo é o valor da data (às vezes com hora): compara o dia\n    return DATE_RE.test(name) ? [{ field, op: 'eq', value: name.slice(0, 10) }] : []\n  }\n  return [{ field, op: 'eq', value: name }]\n}\n\n/** Próximo nível de data ao detalhar (semana vai direto para o dia). */\nexport function nextGranularity(g: string | undefined): string | null {\n  switch (g) {\n    case 'year': return 'quarter'\n    case 'quarter': return 'month'\n    case 'month': return 'day'\n    case 'week': return 'day'\n    default: return null\n  }\n}\n\n// ── Drill-down ────────────────────────────────────────────────────────────────\n\n/** Um nível aberto: o novo agrupamento, o filtro que o abriu e o texto do caminho. */\nexport interface DrillLevel {\n  group_by: string\n  date_granularity?: string\n  conds: BiWidgetCondition[]\n  label: string\n}\n\n/** Como o gráfico está agrupado agora (widget original ou o último nível aberto). */\nfunction currentGroupBy(widget: BiWidget, stack: DrillLevel[]) {\n  const last = stack[stack.length - 1]\n  return last\n    ? { group_by: last.group_by, date_granularity: last.date_granularity }\n    : { group_by: widget.group_by || '', date_granularity: widget.date_granularity }\n}\n\n/** Para onde o \"detalhar\" levaria (null = não há próximo nível). `group` é o agrupamento atual segundo o planejador. */\nexport function drillTarget(widget: BiWidget, stack: DrillLevel[], group: GroupInfo | null | undefined): { group_by: string; date_granularity?: string } | null {\n  if (!widget.drill_detail || !widget.group_by || !group) return null\n  const cur = currentGroupBy(widget, stack)\n  if (group.kind === 'date' && cur.date_granularity) {\n    const next = nextGranularity(cur.date_granularity)\n    if (next) return { group_by: cur.group_by, date_granularity: next }\n  }\n  // dimensão do próximo nível: só uma vez e só se for diferente do agrupamento atual\n  if (widget.drill_by && stack.every(l => l.group_by !== widget.drill_by) && cur.group_by !== widget.drill_by) {\n    return { group_by: widget.drill_by }\n  }\n  return null\n}\n\n/** Abre o próximo nível para o grupo clicado (null se não houver). */\nexport function drillInto(widget: BiWidget, stack: DrillLevel[], group: GroupInfo | null | undefined, name: string): DrillLevel | null {\n  const target = drillTarget(widget, stack, group)\n  if (!target || !group) return null\n  const conds = bucketConditions(group, name)\n  if (conds.length === 0) return null\n  return { ...target, conds, label: name }\n}\n\n/** O widget como deve ser consultado com os níveis abertos (agrupamento do último nível + filtros de todos). */\nexport function applyDrill(widget: BiWidget, stack: DrillLevel[]): BiWidget {\n  if (stack.length === 0) return widget\n  const last = stack[stack.length - 1]\n  return {\n    ...widget,\n    group_by: last.group_by,\n    date_granularity: last.date_granularity,\n    conditions: [...(widget.conditions || []), ...stack.flatMap(l => l.conds)],\n  }\n}\n\n/** Condições do caminho aberto (para \"ver registros\" do nível atual). */\nexport function drillConditions(stack: DrillLevel[]): BiWidgetCondition[] {\n  return stack.flatMap(l => l.conds)\n}\n\n// ── Filtro cruzado ───────────────────────────────────────────────────────────\n\nexport interface CrossFilter {\n  sourceId: string\n  sourceTitle: string\n  /** valor clicado, como aparece no gráfico */\n  name: string\n  conds: BiWidgetCondition[]\n}\n\n/** Cria o filtro cruzado de um clique (null se o grupo não pode virar condição). */\nexport function makeCrossFilter(source: BiWidget, group: GroupInfo | null | undefined, name: string): CrossFilter | null {\n  if (!group) return null\n  const conds = bucketConditions(group, name)\n  if (conds.length === 0) return null\n  return { sourceId: source.id, sourceTitle: source.title || 'Gráfico', name, conds }\n}\n\n/** Condições a somar às do widget `target`: só se ele responde ao filtro cruzado, e nunca as do próprio clique. */\nexport function crossConditionsFor(target: BiWidget, filters: CrossFilter[]): BiWidgetCondition[] {\n  if (!target.cross_target) return []\n  return filters.filter(f => f.sourceId !== target.id).flatMap(f => f.conds)\n}\n\n/** Clicar no mesmo valor de novo limpa o filtro; outro valor do mesmo gráfico o substitui. */\nexport function toggleCrossFilter(current: Record<string, CrossFilter>, next: CrossFilter): Record<string, CrossFilter> {\n  const out = { ...current }\n  if (out[next.sourceId] && out[next.sourceId].name === next.name) delete out[next.sourceId]\n  else out[next.sourceId] = next\n  return out\n}\n",
  "lib/bi/recordsPlan.ts": "/**\n * \"Ver registros\" (drill-down da Fase 4): as linhas da tabela do widget que compõem o número clicado.\n *\n * Usa as mesmas condições do widget (filtros, período, filtro cruzado e o caminho de drill já somados pelo chamador),\n * os mesmos JOINs mínimos e o mesmo vocabulário de SQL do planejador de agregação. Função pura: devolve o SQL.\n */\nimport { getPkColumn } from '../schemaResolver'\nimport { resolveRelations, resolveAllJoins, buildJoinSql, type JoinStep } from '../relationPathFinder'\nimport { findAlternativePaths, pathSignature } from '../relationPaths'\nimport { conditionSql, filterConditionSql, quoteFor, type SqlDialect, type BiCondition, type BiConditionOp, type BiColKind } from './queryBuilder'\nimport { biFieldKind } from './columnKind'\nimport { nextDay, type PeriodRange } from './period'\nimport type { BiWidget } from './widget'\n\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/\nconst FILTER_KEY = /^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z_][A-Za-z0-9_]*)?$/\n\nexport interface RecordsInput {\n  /** widget efetivo: já com os filtros cruzados e o caminho de drill somados em `conditions` */\n  widget: BiWidget\n  models: any[] | Record<string, any>\n  relations: any[]\n  dialect: SqlDialect | null\n  period?: PeriodRange | null\n  screenFilters?: Record<string, string>\n  projectSlug?: string\n  /** máximo de linhas */\n  limit: number\n}\n\nexport interface RecordsPlan {\n  kind: 'records' | 'error'\n  tableName: string\n  schemaName: string\n  sql?: string\n  limit: number\n  message?: string\n}\n\nexport function planRecordsQuery(input: RecordsInput): RecordsPlan {\n  const { widget, dialect, limit } = input\n  const allModels: any[] = Array.isArray(input.models) ? input.models : Object.values(input.models || {})\n  const model = allModels.find(m => String(m.id) === String(widget.model_id))\n  const mainTable: string | null =\n    model?.db_table_name || (typeof widget.model_id === 'string' && widget.model_id !== 'undefined' && !widget.model_id.includes('-') ? widget.model_id : null)\n  const schemaName: string = model?.db_schema_name || input.projectSlug || 'public'\n  const fail = (message: string): RecordsPlan => ({ kind: 'error', tableName: mainTable || '', schemaName, limit, message })\n\n  if (!mainTable || !IDENT.test(mainTable)) return fail('Tabela não encontrada')\n  if (!dialect) return fail('Ver registros exige banco PostgreSQL, Oracle, MySQL ou SQL Server')\n\n  const Q = quoteFor(dialect)\n  const qCol = (t: string, c: string) => `${Q(t)}.${Q(c)}`\n  const resolveRef = (s: string) => (s.includes('.') ? { table: s.split('.')[0], column: s.split('.')[1] } : { table: mainTable, column: s })\n\n  const fieldsOf = (table: string): any[] => {\n    const m = allModels.find(x => x.db_table_name === table)\n    return (Array.isArray(m?.fields) ? m.fields : Object.values(m?.fields || {})) as any[]\n  }\n  const columnExists = (table: string, column: string) => fieldsOf(table).some(f => String(f.db_column_name).toLowerCase() === column.toLowerCase())\n  const colKind = (table: string, column: string): BiColKind =>\n    biFieldKind(fieldsOf(table).find(x => String(x.db_column_name).toLowerCase() === column.toLowerCase()))\n\n  // Condições do widget + período\n  const conditions: BiCondition[] = []\n  for (const c of widget.conditions || []) {\n    if (!c?.field || !c.op) continue\n    const noValue = c.op === 'is_null' || c.op === 'not_null'\n    if (!noValue && (c.value === undefined || c.value === '')) continue\n    if (c.op === 'between' && (c.value2 === undefined || c.value2 === '')) continue\n    const ref = resolveRef(String(c.field))\n    if (!IDENT.test(ref.table) || !IDENT.test(ref.column)) return fail('Filtro com campo inválido')\n    conditions.push({ col: ref, op: c.op as BiConditionOp, kind: colKind(ref.table, ref.column), value: c.value, value2: c.value2 })\n  }\n  if (widget.period_field && input.period) {\n    const ref = resolveRef(widget.period_field)\n    if (IDENT.test(ref.table) && IDENT.test(ref.column)) {\n      conditions.push({ col: ref, op: 'gte', kind: 'date', value: input.period.from })\n      conditions.push({ col: ref, op: 'lt', kind: 'date', value: nextDay(input.period.to) })\n    }\n  }\n\n  // Filtros da tela (\"contém\"): só colunas que existem\n  const filters: { col: { table: string; column: string }; value: string }[] = []\n  for (const [key, val] of Object.entries(input.screenFilters || {})) {\n    if (!val || !FILTER_KEY.test(key)) continue\n    const table = key.includes('.') ? key.split('.')[0] : mainTable\n    const column = key.includes('.') ? key.split('.')[1] : key\n    if (columnExists(table, column)) filters.push({ col: { table, column }, value: String(val) })\n  }\n\n  // JOINs mínimos: só as tabelas citadas pelas condições e filtros\n  const resolvedRelations = resolveRelations(input.relations || [], allModels)\n  const preferred: Record<string, JoinStep[]> = {}\n  for (const [tbl, sig] of Object.entries(widget.relation_paths || {})) {\n    const hit = findAlternativePaths(resolvedRelations, mainTable, tbl).find(p => pathSignature(p) === sig)\n    if (hit) preferred[tbl.toLowerCase()] = hit\n  }\n  const needed = [...new Set([...conditions.map(c => c.col.table), ...filters.map(f => f.col.table)].filter(t => t !== mainTable))]\n  const steps = needed.length > 0 ? resolveAllJoins(resolvedRelations, mainTable, needed, preferred) : []\n  const joined = new Set<string>([mainTable.toLowerCase()])\n  steps.forEach(s => { joined.add(s.fromTable.toLowerCase()); joined.add(s.toTable.toLowerCase()) })\n  const missing = needed.filter(t => !joined.has(t.toLowerCase()))\n  if (missing.length > 0) return fail(`Sem relação entre ${mainTable} e ${missing.join(', ')}`)\n\n  let where: string\n  try {\n    where = ['1=1', ...filters.map(f => filterConditionSql(dialect, f)), ...conditions.map(c => conditionSql(dialect, c))].join(' AND ')\n  } catch (e: any) {\n    return fail(e?.message || 'Filtro inválido')\n  }\n\n  const pk = getPkColumn(allModels, mainTable)\n  const top = dialect === 'sqlserver' ? `TOP ${limit} ` : ''\n  const order = pk && IDENT.test(pk) ? ` ORDER BY ${qCol(mainTable, pk)} DESC` : ''\n  const tail = dialect === 'oracle' ? ` OFFSET 0 ROWS FETCH NEXT ${limit} ROWS ONLY` : dialect === 'sqlserver' ? '' : ` LIMIT ${limit}`\n\n  // Com JOIN para outra tabela uma linha pode repetir: seleciona pelos ids das linhas que casam (sem duplicar)\n  const sql = steps.length > 0 && pk && IDENT.test(pk)\n    ? `SELECT ${top}* FROM ${Q(mainTable)} WHERE ${qCol(mainTable, pk)} IN (SELECT ${qCol(mainTable, pk)} FROM ${Q(mainTable)}${buildJoinSql(steps, undefined, Q)} WHERE ${where})${order}${tail}`\n    : `SELECT ${top}* FROM ${Q(mainTable)}${steps.length > 0 ? buildJoinSql(steps, undefined, Q) : ''} WHERE ${where}${order}${tail}`\n\n  return { kind: 'records', tableName: mainTable, schemaName, sql, limit }\n}\n",
  "lib/bi/shapeResult.ts": "// Transforma as linhas do SQL agregado ({ bi_name, bi_value, bi_series? }) nos dados que o gráfico desenha.\n// Função pura: usada pelo painel em execução (resultado vindo do túnel) e pelo app exportado (resultado da ação de servidor).\n\nimport type { BiWidget } from './widget'\n\nexport interface SeriesTable {\n  rows: Array<Record<string, any>>\n  keys: string[]\n}\n\nexport interface ShapedResult {\n  /** KPI/gauge: número; demais: lista { name, value } */\n  data: number | Array<{ name: string; value: number }>\n  /** gráfico segmentado: tabela com uma coluna por série */\n  series: SeriesTable | null\n  /** havia mais grupos do que o teto: o gráfico mostra só os maiores */\n  truncated: boolean\n}\n\nconst MAX_SERIES = 11\n\nconst read = (r: any, k: string) => r?.[k] ?? r?.[k.toUpperCase()] ?? r?.[k.toLowerCase()]\nconst toNumber = (v: any) => { const n = Number(v); return Number.isFinite(n) ? n : 0 }\nconst label = (v: any) => (v === null || v === undefined || v === '' ? 'N/A' : String(v))\n\nfunction sortRows<T extends { name: string; value: number }>(rows: T[], mode: string | undefined): T[] {\n  if (mode === 'value_asc') return rows.sort((a, b) => a.value - b.value)\n  if (mode === 'label_asc') return rows.sort((a, b) => a.name.localeCompare(b.name))\n  if (mode === 'label_desc') return rows.sort((a, b) => b.name.localeCompare(a.name))\n  return rows.sort((a, b) => b.value - a.value)\n}\n\n/** Valor único do SQL de comparação com o período anterior (KPI). */\nexport function prevValueFromRows(rows: any[] | undefined): number {\n  const v = Number(read(rows?.[0], 'bi_value'))\n  return Number.isFinite(v) ? v : 0\n}\n\nexport function shapeAggRows(widget: BiWidget, rows: any[] | undefined, maxGroups: number): ShapedResult {\n  const list = rows || []\n\n  if (!widget.group_by) {\n    const value = toNumber(read(list[0], 'bi_value'))\n    const data = widget.type === 'kpi' || widget.type === 'gauge' ? value : [{ name: 'Total', value }]\n    return { data, series: null, truncated: false }\n  }\n\n  const hasSeries = !!widget.series_by && ['bar', 'line', 'area'].includes(widget.type) && list.some(r => read(r, 'bi_series') !== undefined)\n  if (hasSeries) {\n    const byName = new Map<string, Record<string, number>>()\n    const seriesTotals = new Map<string, number>()\n    for (const r of list) {\n      const n = label(read(r, 'bi_name'))\n      const sName = label(read(r, 'bi_series'))\n      const v = toNumber(read(r, 'bi_value'))\n      const cur = byName.get(n) || {}\n      cur[sName] = (cur[sName] || 0) + v\n      byName.set(n, cur)\n      seriesTotals.set(sName, (seriesTotals.get(sName) || 0) + v)\n    }\n    // até 11 séries; o restante vira \"Outros\"\n    const ordered = [...seriesTotals.entries()].sort((a, b) => b[1] - a[1]).map(e => e[0])\n    const keep = ordered.slice(0, MAX_SERIES)\n    const others = ordered.slice(MAX_SERIES)\n    const keys = others.length ? [...keep, 'Outros'] : keep\n    let table = [...byName.entries()].map(([name, vals]) => {\n      const row: any = { name, value: 0 }\n      for (const k of keep) { row[k] = vals[k] || 0 }\n      if (others.length) row['Outros'] = others.reduce((a, k) => a + (vals[k] || 0), 0)\n      row.value = keys.reduce((a, k) => a + (row[k] || 0), 0)\n      return row\n    })\n    table = sortRows(table, widget.sort_by)\n    if (widget.limit_top_n && widget.limit_top_n > 0) table = table.slice(0, widget.limit_top_n)\n    return {\n      data: table.map(r => ({ name: r.name, value: r.value })),\n      series: { rows: table, keys },\n      truncated: list.length >= maxGroups * 5,\n    }\n  }\n\n  let finalData = list.map(r => ({ name: label(read(r, 'bi_name')), value: toNumber(read(r, 'bi_value')) }))\n  finalData = sortRows(finalData, widget.sort_by)\n  if (widget.limit_top_n && widget.limit_top_n > 0) finalData = finalData.slice(0, widget.limit_top_n)\n  return { data: finalData, series: null, truncated: !widget.limit_top_n && list.length >= maxGroups }\n}\n",
  "lib/bi/access.ts": "/**\n * Acesso por linha (RLS) do painel de BI.\n *\n * O desenvolvedor cadastra regras do tipo \"só mostre as linhas em que PEDIDOS.VENDEDOR_ID = valor do usuário logado\".\n * Cada regra vira uma condição comum do widget (o planejador cuida de JOINs, tipos e escape), então vale para o\n * indicador, o drill, \"ver registros\" e o filtro cruzado sem código especial.\n *\n * Falha fechada: sem usuário, sem o atributo que a regra pede ou numa tabela sem relação com a coluna da regra, o\n * widget NÃO mostra dados (nunca cai em \"mostrar tudo\").\n */\nimport type { BiWidgetCondition } from './widget'\n\nexport type RlsSource = 'user.email' | 'user.name' | 'user.attr'\n\nexport interface RlsBypass {\n  source: RlsSource\n  /** coluna da tabela de usuários (quando source = 'user.attr') */\n  attr?: string\n  /** quem tiver um destes valores não sofre a regra (ex.: perfil \"admin\") */\n  values: string[]\n}\n\nexport interface RlsRule {\n  id: string\n  /** coluna que limita as linhas (\"tabela.coluna\") */\n  field: string\n  /** 'eq' = igual ao valor do usuário; 'in' = o valor do usuário é uma lista separada por vírgulas */\n  op: 'eq' | 'in'\n  source: RlsSource\n  attr?: string\n  bypass?: RlsBypass\n}\n\n/** Quem está vendo o painel (vem da sessão; nunca do navegador no app exportado). */\nexport interface BiViewer {\n  email?: string | null\n  name?: string | null\n  attrs?: Record<string, unknown> | null\n}\n\nexport type AccessDenied =\n  | { code: 'no_viewer' }\n  | { code: 'missing_value'; detail: string }\n\nexport interface AccessResult {\n  conditions: BiWidgetCondition[]\n  denied?: AccessDenied\n}\n\nconst SOURCES: RlsSource[] = ['user.email', 'user.name', 'user.attr']\nconst MAX_RULES = 20\nconst MAX_BYPASS_VALUES = 50\n\nconst text = (v: unknown, max = 200): string => (typeof v === 'string' ? v.trim().slice(0, max) : '')\n\n/** Valor do usuário para uma fonte; null quando não existe ou está vazio. */\nexport function viewerValue(viewer: BiViewer | null | undefined, source: RlsSource, attr?: string): string | null {\n  if (!viewer) return null\n  let raw: unknown\n  if (source === 'user.email') raw = viewer.email\n  else if (source === 'user.name') raw = viewer.name\n  else if (attr && viewer.attrs) {\n    const key = Object.keys(viewer.attrs).find(k => k.toLowerCase() === attr.toLowerCase())\n    raw = key ? viewer.attrs[key] : undefined\n  }\n  if (raw === null || raw === undefined) return null\n  const s = String(raw).trim()\n  return s === '' ? null : s\n}\n\n/** Limpa as regras vindas de uma configuração salva (descarta o que está incompleto). */\nexport function cleanRlsRules(raw: unknown): RlsRule[] {\n  if (!Array.isArray(raw)) return []\n  const out: RlsRule[] = []\n  for (const r of raw.slice(0, MAX_RULES)) {\n    if (!r || typeof r !== 'object') continue\n    const field = text((r as any).field)\n    const source = (r as any).source as RlsSource\n    if (!field || !SOURCES.includes(source)) continue\n    const attr = text((r as any).attr)\n    if (source === 'user.attr' && !attr) continue\n    const rule: RlsRule = {\n      id: text((r as any).id, 60) || `rls_${out.length + 1}`,\n      field,\n      op: (r as any).op === 'in' ? 'in' : 'eq',\n      source,\n      ...(source === 'user.attr' ? { attr } : {}),\n    }\n    const b = (r as any).bypass\n    if (b && typeof b === 'object' && SOURCES.includes(b.source) && Array.isArray(b.values)) {\n      const values = b.values.map((v: unknown) => text(v)).filter(Boolean).slice(0, MAX_BYPASS_VALUES)\n      const bAttr = text(b.attr)\n      if (values.length > 0 && (b.source !== 'user.attr' || bAttr)) {\n        rule.bypass = { source: b.source, ...(b.source === 'user.attr' ? { attr: bAttr } : {}), values }\n      }\n    }\n    out.push(rule)\n  }\n  return out\n}\n\n/** O usuário está na lista de exceção da regra? (compara sem diferenciar maiúsculas) */\nfunction bypassed(rule: RlsRule, viewer: BiViewer | null | undefined): boolean {\n  if (!rule.bypass) return false\n  const v = viewerValue(viewer, rule.bypass.source, rule.bypass.attr)\n  return v !== null && rule.bypass.values.some(x => x.toLowerCase() === v.toLowerCase())\n}\n\n/** Condições que as regras impõem a este usuário (ou o motivo de negar o acesso). */\nexport function rlsAccess(rules: RlsRule[] | undefined, viewer: BiViewer | null | undefined): AccessResult {\n  const list = rules || []\n  if (list.length === 0) return { conditions: [] }\n  const conditions: BiWidgetCondition[] = []\n  for (const rule of list) {\n    // quem tem exceção na regra não sofre o filtro dela (e não precisa de atributo nenhum)\n    if (bypassed(rule, viewer)) continue\n    if (!viewer) return { conditions: [], denied: { code: 'no_viewer' } }\n    const value = viewerValue(viewer, rule.source, rule.attr)\n    if (value === null) {\n      return { conditions: [], denied: { code: 'missing_value', detail: rule.source === 'user.attr' ? rule.attr || '' : rule.source.replace('user.', '') } }\n    }\n    conditions.push({ field: rule.field, op: rule.op, value })\n  }\n  return { conditions }\n}\n\n/** Soma as condições do acesso às do widget. */\nexport function withAccess<W extends { conditions?: BiWidgetCondition[] }>(widget: W, access: AccessResult): W {\n  return access.conditions.length ? { ...widget, conditions: [...(widget.conditions || []), ...access.conditions] } : widget\n}\n\n/** Colunas da tabela de usuários que as regras consultam (o login as guarda na sessão). */\nexport function rlsAttrColumns(rules: RlsRule[] | undefined): string[] {\n  const cols = new Set<string>()\n  for (const r of rules || []) {\n    if (r.source === 'user.attr' && r.attr) cols.add(r.attr)\n    if (r.bypass?.source === 'user.attr' && r.bypass.attr) cols.add(r.bypass.attr)\n  }\n  return [...cols]\n}\n",
  "lib/bi/perf.ts": "/**\n * Desempenho do painel de BI: cache de resultados, atualização automática e tempo limite.\n * Código puro e sem dependências: roda no painel, no servidor do app exportado e no navegador do app exportado.\n */\n\nexport const CACHE_OPTIONS = [0, 30, 60, 300, 900, 3600] as const\nexport const REFRESH_OPTIONS = [0, 30, 60, 300, 900, 3600] as const\nexport const TIMEOUT_OPTIONS = [10, 15, 30, 60, 120] as const\n\nexport const DEFAULT_TIMEOUT_SECONDS = 30\n\nexport interface BiPerfSettings {\n  /** guarda o resultado de cada consulta por este tempo (0 = sem cache) */\n  cacheSeconds: number\n  /** refaz as consultas sozinho a cada tanto tempo enquanto a tela está aberta (0 = desligado) */\n  refreshSeconds: number\n  /** passado este tempo o indicador mostra \"tempo esgotado\" em vez de ficar carregando */\n  timeoutSeconds: number\n}\n\nconst num = (v: unknown): number => (typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN)\n\n/** Lê os campos gravados em analytics_config (cache_seconds, refresh_seconds, timeout_seconds) com limites seguros. */\nexport function perfSettings(raw: { cache_seconds?: unknown; refresh_seconds?: unknown; timeout_seconds?: unknown } | null | undefined): BiPerfSettings {\n  const cache = num(raw?.cache_seconds)\n  const refresh = num(raw?.refresh_seconds)\n  const timeout = num(raw?.timeout_seconds)\n  return {\n    cacheSeconds: Number.isFinite(cache) ? Math.min(3600, Math.max(0, Math.round(cache))) : 0,\n    // abaixo de 15 s a atualização só sobrecarregaria o banco do cliente\n    refreshSeconds: Number.isFinite(refresh) && refresh >= 15 ? Math.min(86400, Math.round(refresh)) : 0,\n    timeoutSeconds: Number.isFinite(timeout) && timeout > 0 ? Math.min(300, Math.max(5, Math.round(timeout))) : DEFAULT_TIMEOUT_SECONDS,\n  }\n}\n\nexport class BiTimeoutError extends Error {\n  constructor(public readonly ms: number) {\n    super(`tempo esgotado (${Math.round(ms / 1000)}s)`)\n    this.name = 'BiTimeoutError'\n  }\n}\n\n/** Rejeita com BiTimeoutError se a promessa demorar mais que `ms`. (A consulta em si não é cancelada.) */\nexport function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {\n  return new Promise<T>((resolve, reject) => {\n    const timer = setTimeout(() => reject(new BiTimeoutError(ms)), ms)\n    promise.then(\n      v => { clearTimeout(timer); resolve(v) },\n      e => { clearTimeout(timer); reject(e) },\n    )\n  })\n}\n\ninterface Entry<T> { value: T; expires: number }\n\n/**\n * Cache de resultados por chave (a consulta SQL já inclui período, filtros e regras de acesso, então a chave é o\n * próprio SQL). Consultas iguais feitas ao mesmo tempo compartilham uma só ida ao banco.\n */\nexport class QueryCache<T = unknown> {\n  private store = new Map<string, Entry<T>>()\n  private inflight = new Map<string, Promise<T>>()\n\n  constructor(private readonly max = 300, private readonly now: () => number = () => Date.now()) {}\n\n  get size() { return this.store.size }\n\n  get(key: string): T | undefined {\n    const e = this.store.get(key)\n    if (!e) return undefined\n    if (e.expires <= this.now()) { this.store.delete(key); return undefined }\n    // acessado agora: vai para o fim da fila de remoção\n    this.store.delete(key)\n    this.store.set(key, e)\n    return e.value\n  }\n\n  set(key: string, value: T, ttlMs: number) {\n    if (ttlMs <= 0) return\n    this.store.delete(key)\n    this.store.set(key, { value, expires: this.now() + ttlMs })\n    while (this.store.size > this.max) {\n      const oldest = this.store.keys().next().value\n      if (oldest === undefined) break\n      this.store.delete(oldest)\n    }\n  }\n\n  clear() { this.store.clear() }\n\n  /**\n   * Devolve o resultado em cache ou executa `fn`. Com ttl 0 não guarda nada (mas ainda junta chamadas simultâneas\n   * iguais). `fresh` ignora o cache e o substitui pelo resultado novo. Erros nunca ficam em cache.\n   */\n  async run(key: string, ttlMs: number, fn: () => Promise<T>, fresh = false): Promise<{ value: T; cached: boolean }> {\n    if (!fresh && ttlMs > 0) {\n      const hit = this.get(key)\n      if (hit !== undefined) return { value: hit, cached: true }\n    }\n    let pending = fresh ? undefined : this.inflight.get(key)\n    if (!pending) {\n      pending = fn().then(\n        v => { this.inflight.delete(key); this.set(key, v, ttlMs); return v },\n        e => { this.inflight.delete(key); throw e },\n      )\n      this.inflight.set(key, pending)\n    }\n    return { value: await pending, cached: false }\n  }\n}\n",
  "lib/schemaResolver.ts": "/**\n * Resolução de chave primária, chave estrangeira e título de registro a partir dos METADADOS do projeto\n * (modelos, campos, relações). Nenhum nome de tabela/coluna de negócio é assumido.\n *\n * Ordem de decisão: metadado declarado (relação / join do caso de uso / foreign_key_table) → só então, como ÚLTIMO\n * recurso, um palpite por nome (`tabela_id`), sempre sinalizado com console.warn para o desenvolvedor declarar a relação.\n */\n\nconst eq = (a?: string | null, b?: string | null) => !!a && !!b && String(a).toLowerCase() === String(b).toLowerCase()\nconst colOf = (c?: string | null) => (c || '').split('.').pop() || ''\nconst tableOf = (m: any): string => m?.db_table_name ?? m?.table_name ?? ''\n\nexport function findModelByTable(models: any[] | undefined | null, table?: string | null): any | null {\n  if (!table) return null\n  return (models || []).find((m: any) => eq(tableOf(m), table)) || null\n}\n\n/** Campo de chave primária de um modelo: marcado como PK > coluna chamada \"id\" (convenção) > primeira coluna. */\nexport function pickPkField(model: any): any | null {\n  const fields: any[] = model?.fields || []\n  return fields.find((f) => f?.is_primary_key) || fields.find((f) => eq(colOf(f?.db_column_name), 'id')) || fields[0] || null\n}\n\n/** Nome da coluna de chave primária da tabela (metadado), ou null se a tabela não for conhecida. */\nexport function getPkColumn(models: any[] | undefined | null, table?: string | null): string | null {\n  const field = pickPkField(findModelByTable(models, table))\n  const col = colOf(field?.db_column_name)\n  return col || null\n}\n\n/** Lê uma chave do registro ignorando maiúsculas/minúsculas (Oracle devolve colunas em CAIXA ALTA). */\nexport function readCol(record: any, column?: string | null): any {\n  if (!record || !column) return undefined\n  if (record[column] !== undefined) return record[column]\n  const lower = column.toLowerCase()\n  const found = Object.keys(record).find((k) => k.toLowerCase() === lower)\n  return found !== undefined ? record[found] : undefined\n}\n\n/**\n * Valor da chave primária de um registro. Usa a coluna informada (do metadado); só sem ela cai na convenção id/ID.\n * Quando a coluna é informada e o registro não a tem, devolve undefined (não \"inventa\" outro campo).\n */\nexport function getRecordPk(record: any, pkColumn?: string | null): any {\n  if (!record) return undefined\n  if (pkColumn) {\n    const v = readCol(record, pkColumn)\n    if (v !== undefined && v !== null) return v\n    // linhas novas criadas na tela usam \"id\" temporário (convenção do botão \"+\")\n    if (record._isNew) return record.id ?? record.ID\n    return undefined\n  }\n  return record.id ?? record.ID\n}\n\nexport type FkSource = 'relation' | 'join' | 'metadata' | 'name-guess' | 'none'\n\nexport interface FkResolution {\n  column: string | null\n  source: FkSource\n  /** Mais de uma coluna candidata no mesmo nível de decisão (ex.: duas FKs entre as mesmas tabelas). */\n  ambiguous: boolean\n  candidates: string[]\n}\n\ninterface ResolveFkArgs {\n  models?: any[] | null\n  relations?: any[] | null\n  joins?: any[] | null\n  childTable?: string | null\n  parentTable?: string | null\n}\n\nconst uniq = (list: string[]) => Array.from(new Set(list.filter(Boolean)))\n\n/**\n * Coluna da tabela FILHA que aponta para a tabela PAI.\n * 1) relação declarada no projeto  2) join configurado no caso de uso  3) campo da filha com foreign_key_table = pai\n * 4) (último recurso) palpite por nome — sinalizado como 'name-guess'.\n */\nexport function resolveFkColumn({ models, relations, joins, childTable, parentTable }: ResolveFkArgs): FkResolution {\n  const child = findModelByTable(models, childTable)\n  const parent = findModelByTable(models, parentTable)\n\n  // 1) Relações declaradas\n  if (child && parent && relations && relations.length > 0) {\n    const cols: string[] = []\n    for (const r of relations) {\n      const fromId = r.from_model_id ?? r.detail_model_id\n      const toId = r.to_model_id ?? r.master_model_id\n      if (String(fromId) === String(child.id) && String(toId) === String(parent.id)) {\n        const f = child.fields?.find((x: any) => String(x.id) === String(r.from_field_id ?? r.foreign_column_id))\n        if (f) cols.push(colOf(f.db_column_name))\n      } else if (String(toId) === String(child.id) && String(fromId) === String(parent.id)) {\n        // relação gravada no sentido inverso (pai → filho): a FK está no campo \"to\" da filha\n        const f = child.fields?.find((x: any) => String(x.id) === String(r.to_field_id ?? r.referenced_column_id))\n        if (f) cols.push(colOf(f.db_column_name))\n      }\n    }\n    const list = uniq(cols)\n    if (list.length > 0) return { column: list[0], source: 'relation', ambiguous: list.length > 1, candidates: list }\n  }\n\n  // 2) Join configurado no caso de uso\n  if (joins && joins.length > 0) {\n    const matches = joins.filter((j: any) => eq(j.to ?? j.toTable ?? j.table, childTable) && eq(j.from ?? j.table, parentTable))\n    const list = uniq(matches.map((j: any) => colOf(j.foreignKey ?? j.foreign_field ?? j.toOn ?? j.on)))\n    if (list.length > 0) return { column: list[0], source: 'join', ambiguous: list.length > 1, candidates: list }\n  }\n\n  // 3) Metadado do campo (foreign_key_table)\n  if (child && parentTable) {\n    const list = uniq(\n      (child.fields || [])\n        .filter((f: any) => eq(f.foreign_key_table, parentTable))\n        .map((f: any) => colOf(f.db_column_name))\n    )\n    if (list.length > 0) return { column: list[0], source: 'metadata', ambiguous: list.length > 1, candidates: list }\n  }\n\n  // 4) Último recurso: palpite por nome\n  if (child && parentTable) {\n    const p = parentTable.toLowerCase()\n    const singular = p.endsWith('es') ? p.slice(0, -2) : p.endsWith('s') ? p.slice(0, -1) : p\n    const list = uniq(\n      (child.fields || [])\n        .map((f: any) => colOf(f.db_column_name))\n        .filter((c: string) => {\n          const lc = c.toLowerCase()\n          return lc === `${p}_id` || lc === `${singular}_id` || (lc.includes(singular) && lc.endsWith('_id'))\n        })\n    )\n    if (list.length > 0) return { column: list[0], source: 'name-guess', ambiguous: list.length > 1, candidates: list }\n  }\n\n  return { column: null, source: 'none', ambiguous: false, candidates: [] }\n}\n\nconst warned = new Set<string>()\n\n/** Avisa (uma vez por par) quando a relação foi inferida pelo nome ou é ambígua, para o dev declará-la no Studio. */\nexport function warnFkResolution(res: FkResolution, childTable?: string | null, parentTable?: string | null): void {\n  if (res.source !== 'name-guess' && !res.ambiguous) return\n  const key = `${childTable}|${parentTable}|${res.source}|${res.candidates.join(',')}`\n  if (warned.has(key)) return\n  warned.add(key)\n  if (res.source === 'name-guess') {\n    console.warn(\n      `[MetaBuilder] A relação entre \"${parentTable}\" e \"${childTable}\" foi INFERIDA pelo nome da coluna (\"${res.column}\"). ` +\n      `Declare a relação no Studio para não depender de convenção de nomes.`\n    )\n  } else {\n    console.warn(\n      `[MetaBuilder] Mais de uma relação entre \"${parentTable}\" e \"${childTable}\" (${res.candidates.join(', ')}). ` +\n      `Usando \"${res.column}\". Configure o caso de uso com a relação desejada.`\n    )\n  }\n}\n\n/** Mensagem de erro padrão quando nenhuma relação pôde ser determinada. */\nexport function missingRelationMessage(childTable?: string | null, parentTable?: string | null): string {\n  return `Relação entre \"${parentTable}\" e \"${childTable}\" não configurada. Declare a relação no Studio (Relacionamentos) ou configure o vínculo do caso de uso.`\n}\n\nconst TEXT_TYPE = /(char|text|string|citext)/i\n\n/**\n * Título de exibição de um registro quando o caso de uso não configurou um campo de título.\n * Usa os METADADOS: primeiro campo textual visível que não seja chave primária nem chave estrangeira; senão a própria PK.\n * (Antes era um palpite por nomes de coluna em português: nome/titulo/descricao.)\n */\nexport function pickRecordTitle(record: any, model: any): string | undefined {\n  if (!record) return undefined\n  const fields: any[] = model?.fields || []\n  const isFk = (f: any) => !!f.foreign_key_table || !!f.foreign_key_column\n  const candidates = fields.filter(\n    (f) => !f.is_primary_key && !isFk(f) && f.is_visible_in_list !== false && TEXT_TYPE.test(String(f.db_data_type || f.data_type || ''))\n  )\n  for (const f of candidates) {\n    const v = readCol(record, colOf(f.db_column_name))\n    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v)\n  }\n  const pk = getRecordPk(record, getPkColumn([model], tableOf(model)))\n  return pk !== undefined && pk !== null ? String(pk) : undefined\n}\n\nexport interface InferredJoin { from: string; localKey: string; to: string; foreignKey: string }\n\n/**\n * Joins pai→filho deduzidas do esquema, quando o caso de uso e as relações do projeto não trazem nenhuma.\n * Por par de tabelas: 1) campo da filha com foreign_key_table = pai (metadado)  2) último recurso, palpite por nome (avisado).\n * A chave do pai é a PK do metadado (e não uma coluna chamada \"id\").\n */\nexport function inferJoins(models: any[] | undefined | null, onlyParentTable?: string | null): InferredJoin[] {\n  const out: InferredJoin[] = []\n  const all = models || []\n  for (const parent of all) {\n    if (onlyParentTable && !eq(tableOf(parent), onlyParentTable)) continue\n    const pk = pickPkField(parent)\n    if (!pk) continue\n    for (const child of all) {\n      if (child.id === parent.id) continue\n      const res = resolveFkColumn({ models: all, childTable: tableOf(child), parentTable: tableOf(parent) })\n      if (!res.column || (res.source !== 'metadata' && res.source !== 'name-guess')) continue\n      warnFkResolution(res, tableOf(child), tableOf(parent))\n      const fkField = (child.fields || []).find((f: any) => eq(colOf(f.db_column_name), res.column))\n      out.push({\n        from: tableOf(parent),\n        localKey: pk.db_column_name,\n        to: tableOf(child),\n        foreignKey: fkField?.db_column_name ?? res.column,\n      })\n    }\n  }\n  return out\n}\n\nconst warnedRefs = new Set<string>()\n/** Avisa (uma vez) que a tabela referenciada por uma coluna foi deduzida pelo NOME da coluna (sem metadado). */\nexport function warnInferredReference(column?: string | null, table?: string | null): void {\n  const key = `${column}|${table}`\n  if (warnedRefs.has(key)) return\n  warnedRefs.add(key)\n  console.warn(`[MetaBuilder] A coluna \"${column}\" foi associada à tabela \"${table}\" apenas pelo NOME. Declare a relação/chave estrangeira no Studio para não depender de convenção de nomes.`)\n}\n\n/** Campo de chave primária da tabela pelo METADADO; só se a tabela não for conhecida devolve { db_column_name: 'id' }. */\nexport function getPkFieldOrDefault(models: any[] | undefined | null, table?: string | null): any {\n  return pickPkField(findModelByTable(models, table)) || { db_column_name: 'id' }\n}\n\n/**\n * Texto que identifica um registro para o usuário (ex.: confirmação de exclusão).\n * Ordem: campo configurado no Studio (ex.: subtítulo do formulário) > primeiro campo textual do modelo > chave primária.\n */\nexport function resolveRecordLabel(record: any, model: any, configuredField?: string | null): string | undefined {\n  if (!record) return undefined\n  if (configuredField) {\n    const direct = record[configuredField] ?? readCol(record, colOf(configuredField))\n    if (direct !== undefined && direct !== null && String(direct).trim() !== '') return String(direct)\n  }\n  return pickRecordTitle(record, model)\n}\n",
  "lib/relationPathFinder.ts": "/**\n * Santo Graal — Biblioteca de Path-Finding por BFS\n *\n * Resolve automaticamente o caminho de JOINs entre quaisquer duas tabelas\n * usando o grafo de relações do projeto (tabela `relations` do Supabase).\n *\n * Algoritmo: BFS (Busca em Largura) — garante o caminho mais curto.\n * Suporta ciclos (nós visitados), múltiplos caminhos (BFS escolhe o mais curto)\n * e relações bidirecionais.\n */\n\n// ─── Tipos ────────────────────────────────────────────────────────────────────\n\nexport interface ResolvedRelation {\n  id: string\n  from_table: string   // db_table_name já resolvido\n  from_field: string   // db_column_name já resolvido\n  to_table: string\n  to_field: string\n  relation_type?: string\n  source?: 'cli' | 'manual'\n}\n\nexport interface JoinStep {\n  fromTable: string\n  fromField: string\n  toTable: string\n  toField: string\n}\n\n// ─── Resolução de Relações ────────────────────────────────────────────────────\n\n/**\n * Converte a estrutura raw da tabela `relations` (com UUIDs de model/field)\n * para `ResolvedRelation` com nomes reais de tabela e coluna.\n * Deve ser chamada UMA vez ao carregar o projeto.\n */\nexport function resolveRelations(\n  rawRelations: any[],\n  models: any[]\n): ResolvedRelation[] {\n  const resolved: ResolvedRelation[] = []\n\n  for (const rel of rawRelations) {\n    // Resolve modelo de origem\n    const fromModel = models.find((m: any) =>\n      String(m.id) === String(rel.from_model_id)\n    )\n    // Resolve modelo de destino\n    const toModel = models.find((m: any) =>\n      String(m.id) === String(rel.to_model_id)\n    )\n\n    if (!fromModel || !toModel) continue\n\n    // Resolve campo de origem (FK)\n    const fromFields = Array.isArray(fromModel.fields)\n      ? fromModel.fields\n      : Object.values(fromModel.fields || {})\n    const fromField = fromFields.find((f: any) =>\n      String(f.id) === String(rel.from_field_id)\n    )\n\n    // Resolve campo de destino (PK referenciada)\n    const toFields = Array.isArray(toModel.fields)\n      ? toModel.fields\n      : Object.values(toModel.fields || {})\n    const toField = toFields.find((f: any) =>\n      String(f.id) === String(rel.to_field_id)\n    )\n\n    if (!fromField || !toField) continue\n\n    resolved.push({\n      id: rel.id,\n      from_table: fromModel.db_table_name,\n      from_field: fromField.db_column_name,\n      to_table: toModel.db_table_name,\n      to_field: toField.db_column_name,\n      relation_type: rel.relation_type,\n      source: rel.source || 'cli',\n    })\n  }\n\n  return resolved\n}\n\n// ─── BFS: Caminho entre Duas Tabelas ─────────────────────────────────────────\n\n/**\n * Encontra o caminho de JOINs mais curto entre `fromTable` e `toTable`\n * usando BFS no grafo de relações.\n *\n * @returns Array de JoinStep em ordem, ou null se não há caminho.\n */\nexport function findJoinPath(\n  relations: ResolvedRelation[],\n  fromTable: string,\n  toTable: string\n): JoinStep[] | null {\n  if (fromTable.toLowerCase() === toTable.toLowerCase()) return []\n\n  // Cada entrada na fila é o caminho percorrido até aqui\n  const queue: Array<{ table: string; path: JoinStep[] }> = [\n    { table: fromTable.toLowerCase(), path: [] },\n  ]\n  const visited = new Set<string>([fromTable.toLowerCase()])\n\n  while (queue.length > 0) {\n    const { table: current, path } = queue.shift()!\n\n    // Busca todas as relações onde `current` aparece (em qualquer lado)\n    const neighbors = getNeighbors(relations, current)\n\n    for (const { step, neighborTable } of neighbors) {\n      if (visited.has(neighborTable)) continue\n      visited.add(neighborTable)\n\n      const newPath = [...path, step]\n\n      if (neighborTable === toTable.toLowerCase()) {\n        return newPath\n      }\n\n      queue.push({ table: neighborTable, path: newPath })\n    }\n  }\n\n  return null // Sem caminho\n}\n\n/**\n * Retorna os vizinhos de uma tabela no grafo de relações (bidirecional).\n */\nexport function getNeighbors(\n  relations: ResolvedRelation[],\n  tableName: string\n): Array<{ step: JoinStep; neighborTable: string }> {\n  const result: Array<{ step: JoinStep; neighborTable: string }> = []\n  const lower = tableName.toLowerCase()\n\n  for (const rel of relations) {\n    const fromLower = rel.from_table.toLowerCase()\n    const toLower = rel.to_table.toLowerCase()\n\n    if (fromLower === lower) {\n      // Relação direta: from_table → to_table\n      result.push({\n        neighborTable: toLower,\n        step: {\n          fromTable: rel.from_table,\n          fromField: rel.from_field,\n          toTable: rel.to_table,\n          toField: rel.to_field,\n        },\n      })\n    } else if (toLower === lower) {\n      // Relação inversa: to_table → from_table\n      result.push({\n        neighborTable: fromLower,\n        step: {\n          fromTable: rel.to_table,\n          fromField: rel.to_field,\n          toTable: rel.from_table,\n          toField: rel.from_field,\n        },\n      })\n    }\n  }\n\n  return result\n}\n\n// ─── Resolve Múltiplas Tabelas (Spanning Tree) ────────────────────────────────\n\n/**\n * Dado um conjunto de tabelas que precisam estar no SELECT,\n * encontra todos os JOINs necessários para conectá-las à tabela raiz.\n *\n * Usa uma abordagem de spanning tree: começa com `rootTable` e vai\n * adicionando joins para cada tabela adicional, usando o grafo de relações.\n *\n * @param relations - Relações resolvidas do projeto\n * @param rootTable - Tabela principal da query (FROM)\n * @param additionalTables - Demais tabelas que precisam ser incluídas\n * @returns Array de JoinStep sem duplicatas, em ordem de dependência\n */\nexport function resolveAllJoins(\n  relations: ResolvedRelation[],\n  rootTable: string,\n  additionalTables: string[],\n  /** caminho escolhido pelo desenvolvedor por tabela (chave em minúsculas); sem escolha vale o mais curto (BFS) */\n  preferred?: Record<string, JoinStep[]>\n): JoinStep[] {\n  const joinedTables = new Set<string>([rootTable.toLowerCase()])\n  const allSteps: JoinStep[] = []\n  const seenJoinKeys = new Set<string>()\n\n  // Tabelas únicas e diferentes da raiz\n  const uniqueTables = [\n    ...new Set(\n      additionalTables\n        .map(t => t.toLowerCase())\n        .filter(t => t && t !== rootTable.toLowerCase())\n    ),\n  ]\n\n  // Caminhos escolhidos pelo desenvolvedor entram primeiro (e têm prioridade sobre o mais curto)\n  for (const target of uniqueTables) {\n    const chosen = preferred?.[target]\n    if (!chosen || chosen.length === 0) continue\n    for (const step of chosen) {\n      const key = `${step.fromTable}.${step.fromField}→${step.toTable}.${step.toField}`\n      const reverseKey = `${step.toTable}.${step.toField}→${step.fromTable}.${step.fromField}`\n      if (!seenJoinKeys.has(key) && !seenJoinKeys.has(reverseKey)) {\n        allSteps.push(step)\n        seenJoinKeys.add(key)\n      }\n      joinedTables.add(step.fromTable.toLowerCase())\n      joinedTables.add(step.toTable.toLowerCase())\n    }\n  }\n\n  // Tenta adicionar cada tabela necessária usando BFS\n  // Iteração em loop para suportar dependências transitivas\n  let changed = true\n  let safety = 0\n\n  while (changed && uniqueTables.some(t => !joinedTables.has(t)) && safety < 20) {\n    changed = false\n    safety++\n\n    for (const targetTable of uniqueTables) {\n      if (joinedTables.has(targetTable)) continue\n\n      // Tenta encontrar um caminho de qualquer tabela já joined para targetTable\n      let bestPath: JoinStep[] | null = null\n\n      for (const joinedTable of Array.from(joinedTables)) {\n        const path = findJoinPath(relations, joinedTable, targetTable)\n        if (path && path.length > 0) {\n          if (!bestPath || path.length < bestPath.length) {\n            bestPath = path\n          }\n        }\n      }\n\n      if (bestPath) {\n        // Adiciona apenas os passos que ainda não foram adicionados\n        for (const step of bestPath) {\n          const key = `${step.fromTable}.${step.fromField}→${step.toTable}.${step.toField}`\n          const reverseKey = `${step.toTable}.${step.toField}→${step.fromTable}.${step.fromField}`\n\n          if (!seenJoinKeys.has(key) && !seenJoinKeys.has(reverseKey)) {\n            allSteps.push(step)\n            seenJoinKeys.add(key)\n          }\n\n          joinedTables.add(step.fromTable.toLowerCase())\n          joinedTables.add(step.toTable.toLowerCase())\n        }\n        changed = true\n      }\n    }\n  }\n\n  return allSteps\n}\n\n// ─── Geração de SQL ────────────────────────────────────────────────────────────\n\n/**\n * Converte um array de JoinStep em cláusula SQL de LEFT JOINs.\n */\nexport function buildJoinSql(\n  steps: JoinStep[],\n  filterTables?: Set<string>,\n  /** delimitador de identificador do banco (padrão: aspas duplas; MySQL usa crase e SQL Server colchetes) */\n  quote: (id: string) => string = id => `\"${id}\"`\n): string {\n  return steps\n    .map(s => {\n      const joinType = filterTables?.has(s.toTable.toLowerCase()) ? 'INNER JOIN' : 'LEFT JOIN'\n      return ` ${joinType} ${quote(s.toTable)} ON ${quote(s.fromTable)}.${quote(s.fromField)} = ${quote(s.toTable)}.${quote(s.toField)}`\n    })\n    .join('')\n}\n\n/**\n * Extrai os nomes de tabela únicos de uma lista de campos no formato \"tabela.campo\".\n * Ignora campos sem ponto (que são da tabela raiz).\n */\nexport function extractTableNames(fieldExpressions: string[]): string[] {\n  const tables = new Set<string>()\n  for (const expr of fieldExpressions) {\n    if (expr && expr.includes('.')) {\n      const table = expr.split('.')[0].replace(/\"/g, '')\n      if (table) tables.add(table)\n    }\n  }\n  return Array.from(tables)\n}\n\n/**\n * Verificação rápida: retorna true se existe um caminho entre duas tabelas.\n */\nexport function hasPath(\n  relations: ResolvedRelation[],\n  fromTable: string,\n  toTable: string\n): boolean {\n  return findJoinPath(relations, fromTable, toTable) !== null\n}\n\nexport function getModelsWithRelations(\n  baseModels: any[], \n  relations: any[], \n  models: any[], \n  maxDepth = 2\n) {\n  const result: any[] = [];\n  const baseModelIds = baseModels.map(m => m.id);\n\n  baseModels.forEach(baseModel => {\n    const queue = [{\n      model: baseModel,\n      depth: 0,\n      path: baseModel.db_table_name,\n      prefix: '',\n      relation_path: [] as any[]\n    }];\n\n    const visitedIds = new Set<string>();\n\n    while (queue.length > 0) {\n      const current = queue.shift()!;\n      \n      if (visitedIds.has(current.model.id)) continue;\n      visitedIds.add(current.model.id);\n\n      if (current.depth === 0) {\n        result.push({\n          model: current.model,\n          prefix: '',\n          label: `Tabela: ${current.model.db_table_name}`\n        });\n      } else {\n        result.push({\n          model: current.model,\n          prefix: `${current.model.db_table_name}.`,\n          label: `Relação: ${current.path}`,\n          relation_path: current.relation_path\n        });\n      }\n\n      if (current.depth < maxDepth) {\n        const explicitRels = (relations || []).filter((r: any) => \n          r.from_model_id === current.model.id || r.to_model_id === current.model.id\n        );\n\n        const relatedModelsInfo = explicitRels.map((r: any) => {\n          let toModelId = null;\n          if (r.from_model_id === current.model.id) toModelId = r.to_model_id;\n          if (r.to_model_id === current.model.id) toModelId = r.from_model_id;\n          if (!toModelId) return null;\n          return { toModelId, relation: r };\n        }).filter(Boolean);\n\n        const uniqueRelatedInfos: any[] = [];\n        const seenIds = new Set();\n        relatedModelsInfo.forEach((info: any) => {\n           if (!seenIds.has(info.toModelId)) {\n               seenIds.add(info.toModelId);\n               uniqueRelatedInfos.push(info);\n           }\n        });\n\n        uniqueRelatedInfos.forEach((info: any) => {\n          const relatedId = info.toModelId;\n          const relation = info.relation;\n          \n          if (!visitedIds.has(relatedId) && !baseModelIds.includes(relatedId)) {\n            const relatedModel = models.find((m: any) => m.id === relatedId);\n            if (relatedModel) {\n              queue.push({\n                model: relatedModel,\n                depth: current.depth + 1,\n                path: `${current.path} > ${relatedModel.db_table_name}`,\n                prefix: `${relatedModel.db_table_name}.`,\n                relation_path: [\n                   ...(current.relation_path || []),\n                   {\n                      step: current.depth + 1,\n                      relation_id: relation.id,\n                      from_model_id: relation.from_model_id || relation.detail_model_id,\n                      to_model_id: relation.to_model_id || relation.master_model_id,\n                      foreign_column_id: relation.from_field_id || relation.foreign_column_id\n                   }\n                ]\n              });\n            }\n          }\n        });\n      }\n    }\n  });\n\n  const uniqueResult: any[] = [];\n  const seenPrefixes = new Set();\n  result.forEach(item => {\n    const key = item.prefix || item.model.id;\n    if (!seenPrefixes.has(key)) {\n      seenPrefixes.add(key);\n      uniqueResult.push(item);\n    }\n  });\n  return uniqueResult;\n}\n\n/**\n * Resolves a relational filter across tables dynamically using the BFS path.\n * If targetTable is separated by 1 or more hops from modelName, it traverses\n * backwards from targetTable to modelName querying intermediate foreign keys.\n */\nexport async function resolveRelationalFilter(\n  supabaseClient: any,\n  relations: ResolvedRelation[],\n  modelName: string,\n  targetTable: string,\n  targetCol: string,\n  targetVal: any\n): Promise<{ type: 'eq'; column: string; value: any } | { type: 'in'; column: string; values: any[] } | { type: 'empty' } | null> {\n  const path = findJoinPath(relations, modelName, targetTable)\n  if (!path || path.length === 0) {\n    // Dynamic fallback if relations graph has no explicit entry\n    const cleanModel = modelName.toLowerCase()\n    const modelSingular = cleanModel.endsWith('s') ? cleanModel.slice(0, -1) : cleanModel\n    const possibleFkOnTarget = [cleanModel + '_id', modelSingular + '_id']\n\n    for (const fk of possibleFkOnTarget) {\n      try {\n        const { data: targetRows } = await supabaseClient\n          .from(targetTable)\n          .select(fk)\n          .eq(targetCol, targetVal)\n        if (targetRows && targetRows.length > 0) {\n          const ids = Array.from(new Set(targetRows.map((r: any) => r[fk]).filter(Boolean)))\n          if (ids.length === 0) return { type: 'empty' }\n          return { type: 'in', column: 'id', values: ids }\n        }\n      } catch (_) {}\n    }\n\n    return null\n  }\n\n  // 1-step direct relationship\n  if (path.length === 1) {\n    const step = path[0]\n    if (step.toField === targetCol) {\n      return { type: 'eq', column: step.fromField, value: targetVal }\n    }\n  }\n\n  // Multi-step traversal backwards from targetTable to modelName\n  let currentValues = [targetVal]\n\n  for (let i = path.length - 1; i >= 1; i--) {\n    const currentStep = path[i]\n    const prevStep = path[i - 1]\n\n    const queryTable = currentStep.fromTable\n    const matchCol = currentStep.fromField\n    const extractCol = prevStep.toField\n\n    const { data, error } = await supabaseClient\n      .from(queryTable)\n      .select(extractCol)\n      .in(matchCol, currentValues)\n\n    if (error || !data || data.length === 0) {\n      return { type: 'empty' }\n    }\n\n    currentValues = Array.from(new Set(data.map((r: any) => r[extractCol]).filter(Boolean)))\n    if (currentValues.length === 0) {\n      return { type: 'empty' }\n    }\n  }\n\n  const masterCol = path[0].fromField\n  return { type: 'in', column: masterCol, values: currentValues }\n}\n\n",
  "lib/relationPaths.ts": "/**\n * Caminhos alternativos entre tabelas.\n *\n * O motor (relationPathFinder) sempre liga duas tabelas pelo caminho mais curto. Quando existe mais de uma forma de ligar\n * (duas chaves entre as mesmas tabelas, ou rotas diferentes de mesmo tamanho), o resultado depende de qual foi escolhida\n * e, antes, a escolha era implícita. Aqui listamos as alternativas para o desenvolvedor decidir.\n */\nimport { getNeighbors, findJoinPath, type ResolvedRelation, type JoinStep } from './relationPathFinder'\n\nexport interface PathSearchOptions {\n  /** aceita caminhos até N passos mais longos que o mais curto (padrão 1) */\n  maxExtraLength?: number\n  maxPaths?: number\n  maxDepth?: number\n}\n\nexport const DEFAULT_PATH_OPTIONS: Required<PathSearchOptions> = { maxExtraLength: 1, maxPaths: 8, maxDepth: 5 }\n\n/** Identificador estável de um caminho (é o que o widget guarda). */\nexport function pathSignature(steps: JoinStep[]): string {\n  return steps.map(s => `${s.fromTable}.${s.fromField}>${s.toTable}.${s.toField}`.toLowerCase()).join('|')\n}\n\n/** Todos os caminhos simples (sem repetir tabela) de `from` até `to`, do mais curto para o mais longo. */\nexport function findAlternativePaths(\n  relations: ResolvedRelation[],\n  from: string,\n  to: string,\n  options: PathSearchOptions = {},\n): JoinStep[][] {\n  const { maxExtraLength, maxPaths, maxDepth } = { ...DEFAULT_PATH_OPTIONS, ...options }\n  const fromL = from.toLowerCase()\n  const toL = to.toLowerCase()\n  if (fromL === toL) return []\n\n  const found: JoinStep[][] = []\n  const dfs = (table: string, visited: Set<string>, path: JoinStep[]) => {\n    if (path.length >= maxDepth) return\n    for (const { step, neighborTable } of getNeighbors(relations, table)) {\n      if (visited.has(neighborTable)) continue\n      const next = [...path, step]\n      if (neighborTable === toL) { found.push(next); continue }\n      visited.add(neighborTable)\n      dfs(neighborTable, visited, next)\n      visited.delete(neighborTable)\n    }\n  }\n  dfs(fromL, new Set([fromL]), [])\n  if (found.length === 0) return []\n\n  found.sort((a, b) => a.length - b.length)\n  const limit = found[0].length + maxExtraLength\n  const seen = new Set<string>()\n  const out: JoinStep[][] = []\n  for (const p of found) {\n    if (p.length > limit) break\n    const sig = pathSignature(p)\n    if (seen.has(sig)) continue\n    seen.add(sig)\n    out.push(p)\n    if (out.length >= maxPaths) break\n  }\n  return out\n}\n\n/** O caminho que o motor usa quando o desenvolvedor não escolhe (o mais curto, por busca em largura). */\nexport function automaticPath(relations: ResolvedRelation[], from: string, to: string): JoinStep[] | null {\n  return findJoinPath(relations, from, to)\n}\n\n/** \"pedidos.funcionario_id → funcionarios.id › funcionarios.depto_id → departamentos.id\" */\nexport function describePath(steps: JoinStep[], labelOf: (table: string) => string = t => t): string {\n  return steps.map(s => `${labelOf(s.fromTable)}.${s.fromField} → ${labelOf(s.toTable)}.${s.toField}`).join('  ›  ')\n}\n\n/** Tabelas (além da principal) para as quais existe mais de um caminho possível. */\nexport function ambiguousTables(\n  relations: ResolvedRelation[],\n  mainTable: string,\n  tables: string[],\n  options?: PathSearchOptions,\n): { table: string; paths: JoinStep[][] }[] {\n  const out: { table: string; paths: JoinStep[][] }[] = []\n  for (const t of tables) {\n    if (t.toLowerCase() === mainTable.toLowerCase()) continue\n    const paths = findAlternativePaths(relations, mainTable, t, options)\n    if (paths.length > 1) out.push({ table: t, paths })\n  }\n  return out\n}\n",
}

// Acesso a dados por tabela (permissões e regras por linha do usuário final), copiado para o app exportado (lib/rowPolicy/*).
export const ACCESS_RUNTIME_FILES: Record<string, string> = {
  "lib/rowPolicy/policy.ts": "/**\n * Acesso a dados do usuário final por TABELA (permissões de criar/editar/excluir e acesso por linha).\n *\n * O desenvolvedor configura em Dados & Schemas, em cada tabela. O servidor resolve a política para quem está logado\n * (sessão assinada), e o resultado (`access`) vai dentro do comando assinado ao Agente CLI, que a aplica no SQL\n * (cli/sqlPolicy.js). Este arquivo é puro: lê a configuração salva, limpa e resolve para um usuário.\n *\n * Sem regra numa tabela, todos veem todas as linhas dela (como antes): a política é opcional e por tabela.\n */\nimport { viewerValue, type BiViewer, type RlsBypass, type RlsSource } from '../bi/access'\nimport type { AuditColumns, EffectiveAudit } from './audit'\n\nexport type PolicyOp = 'eq' | 'in' | 'related'\n\nexport interface RowPolicyRule {\n  id: string\n  /** coluna DESTA tabela que limita as linhas */\n  column: string\n  /** 'eq' = igual ao valor do usuário; 'in' = o valor do usuário é uma lista separada por vírgulas;\n   *  'related' = a coluna aponta para uma linha de outra tabela cuja coluna `related.column` é igual ao valor do usuário */\n  op: PolicyOp\n  source: RlsSource\n  attr?: string\n  related?: { table: string; key: string; column: string }\n  /** quem tiver um destes valores não sofre a regra (ex.: perfil \"admin\") */\n  bypass?: RlsBypass\n}\n\nexport interface RowPolicy { rules: RowPolicyRule[] }\n\n/** O que vai dentro do comando assinado (formato lido por cli/sqlPolicy.js). */\nexport interface AccessCond { column: string; op: PolicyOp; values: string[]; related?: { table: string; key: string; column: string } }\nexport interface AccessPolicy { table: string; deny?: true; conds: AccessCond[] }\nexport interface AccessFlags { create?: boolean; update?: boolean; delete?: boolean }\n/** Auditoria de uma tabela: as colunas e o valor do usuário que vai nas colunas `*_por` (null = sem o dado: ficam vazias). */\nexport type AccessAudit = AuditColumns & { actor?: string | null }\nexport interface AccessPayload { policies: AccessPolicy[]; flags: Record<string, AccessFlags>; audit?: Record<string, AccessAudit> }\n\n/** O que a configuração salva de cada tabela do projeto contém. */\nexport interface TableAccessConfig {\n  table: string\n  canCreate: boolean\n  canUpdate: boolean\n  canDelete: boolean\n  policy: RowPolicy | null\n  /** auditoria da tabela (já resolvida: configurada ou reconhecida pelo nome); null = sem auditoria */\n  audit?: EffectiveAudit | null\n}\n\nconst SOURCES: RlsSource[] = ['user.email', 'user.name', 'user.attr']\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/\nconst MAX_RULES = 10\nconst MAX_BYPASS_VALUES = 50\nconst MAX_LIST_VALUES = 100\n\nconst text = (v: unknown, max = 200): string => (typeof v === 'string' ? v.trim().slice(0, max) : '')\nconst ident = (v: unknown): string => { const s = text(v, 100); return IDENT.test(s) ? s : '' }\n\n/** Limpa a política vinda do banco/da tela (descarta o que está incompleto ou com nome inválido). */\nexport function cleanRowPolicy(raw: unknown): RowPolicy | null {\n  const list = raw && typeof raw === 'object' ? (raw as any).rules : null\n  if (!Array.isArray(list)) return null\n  const rules: RowPolicyRule[] = []\n  for (const r of list.slice(0, MAX_RULES)) {\n    if (!r || typeof r !== 'object') continue\n    const column = ident((r as any).column)\n    const source = (r as any).source as RlsSource\n    if (!column || !SOURCES.includes(source)) continue\n    const attr = text((r as any).attr)\n    if (source === 'user.attr' && !attr) continue\n    const op: PolicyOp = (r as any).op === 'in' ? 'in' : (r as any).op === 'related' ? 'related' : 'eq'\n    const rule: RowPolicyRule = { id: text((r as any).id, 60) || `rp_${rules.length + 1}`, column, op, source, ...(source === 'user.attr' ? { attr } : {}) }\n    if (op === 'related') {\n      const rel = (r as any).related\n      const table = ident(rel?.table), key = ident(rel?.key), col = ident(rel?.column)\n      if (!table || !key || !col) continue\n      rule.related = { table, key, column: col }\n    }\n    const b = (r as any).bypass\n    if (b && typeof b === 'object' && SOURCES.includes(b.source) && Array.isArray(b.values)) {\n      const values = b.values.map((v: unknown) => text(v)).filter(Boolean).slice(0, MAX_BYPASS_VALUES)\n      const bAttr = text(b.attr)\n      if (values.length > 0 && (b.source !== 'user.attr' || bAttr)) rule.bypass = { source: b.source, ...(b.source === 'user.attr' ? { attr: bAttr } : {}), values }\n    }\n    rules.push(rule)\n  }\n  return rules.length ? { rules } : null\n}\n\nconst bypassed = (rule: RowPolicyRule, viewer: BiViewer | null): boolean => {\n  if (!rule.bypass) return false\n  const v = viewerValue(viewer, rule.bypass.source, rule.bypass.attr)\n  return v !== null && rule.bypass.values.some(x => x.toLowerCase() === v.toLowerCase())\n}\n\n/**\n * Resolve as tabelas do projeto para UM usuário: quais restrições valem para ele.\n * Falha fechada: sem usuário, ou sem o dado que a regra exige, a tabela fica negada (nenhuma linha).\n * Só entram no resultado as tabelas que têm algo a impor (o resto não precisa ir no comando).\n */\nexport function resolveAccess(configs: TableAccessConfig[], viewer: BiViewer | null): AccessPayload {\n  const policies: AccessPolicy[] = []\n  const flags: Record<string, AccessFlags> = {}\n  const audit: Record<string, AccessAudit> = {}\n\n  for (const c of configs) {\n    const table = c.table.toLowerCase()\n    if (c.audit) {\n      const actor = viewerValue(viewer, c.audit.by.source, c.audit.by.attr)\n      audit[table] = { ...c.audit.columns, actor }\n    }\n    if (!c.canCreate || !c.canUpdate || !c.canDelete) {\n      flags[table] = {\n        ...(c.canCreate ? {} : { create: false }),\n        ...(c.canUpdate ? {} : { update: false }),\n        ...(c.canDelete ? {} : { delete: false }),\n      }\n    }\n    if (!c.policy || c.policy.rules.length === 0) continue\n\n    const conds: AccessCond[] = []\n    let denied = false\n    for (const rule of c.policy.rules) {\n      if (bypassed(rule, viewer)) continue\n      const value = viewerValue(viewer, rule.source, rule.attr)\n      if (value === null) { denied = true; break }\n      let values = [value]\n      if (rule.op === 'in') {\n        values = value.split(',').map(v => v.trim()).filter(Boolean).slice(0, MAX_LIST_VALUES)\n        if (values.length === 0) { denied = true; break }\n      }\n      conds.push({ column: rule.column, op: rule.op, values, ...(rule.op === 'related' ? { related: rule.related } : {}) })\n    }\n    if (denied) policies.push({ table, deny: true, conds: [] })\n    else if (conds.length > 0) policies.push({ table, conds })\n  }\n  return { policies, flags, ...(Object.keys(audit).length ? { audit } : {}) }\n}\n",
  "lib/rowPolicy/audit.ts": "/**\n * Auditoria por tabela: quando e por quem cada registro foi criado/alterado.\n *\n * O dev escolhe (ou o sistema reconhece pelo nome) quatro colunas da tabela. Quem PREENCHE é o servidor (o Agente CLI, ou o\n * app exportado), nunca a tela: o que o navegador mandar nessas colunas é descartado, `criado_*` não muda depois de criado e\n * `*_por` recebe o dado do usuário logado (o id, por padrão), lido da sessão assinada.\n *\n * Este arquivo é puro e é copiado para o app exportado (lib/rowPolicy/audit.ts).\n */\nimport type { RlsSource } from '../bi/access'\n\nexport interface AuditColumns {\n  createdAt?: string\n  createdBy?: string\n  updatedAt?: string\n  updatedBy?: string\n}\n\n/** O que vai gravado em `models.audit_config`. Sem nada salvo, vale o reconhecimento pelo nome. */\nexport interface AuditConfig extends AuditColumns {\n  /** auditoria desligada nesta tabela (nem o reconhecimento pelo nome vale) */\n  disabled?: boolean\n  /** de onde vem o valor das colunas `*_por`: o id do usuário (padrão), o e-mail, o nome ou outra coluna do cadastro dele */\n  by?: { source: RlsSource; attr?: string }\n}\n\nexport const DEFAULT_AUDIT_BY: { source: RlsSource; attr?: string } = { source: 'user.attr', attr: 'id' }\n\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/\nconst ident = (v: unknown): string | undefined => (typeof v === 'string' && IDENT.test(v.trim()) ? v.trim() : undefined)\n\n/** Nomes comuns (português e inglês), em ordem de preferência, de cada coluna de auditoria. */\nconst CANDIDATES: Record<keyof AuditColumns, string[]> = {\n  createdAt: ['criado_em', 'created_at', 'data_criacao', 'dt_criacao', 'createdat', 'criadoem'],\n  createdBy: ['criado_por', 'created_by', 'usuario_criacao', 'createdby', 'criadopor'],\n  updatedAt: ['atualizado_em', 'updated_at', 'data_atualizacao', 'dt_atualizacao', 'updatedat', 'atualizadoem'],\n  updatedBy: ['atualizado_por', 'updated_by', 'usuario_atualizacao', 'updatedby', 'atualizadopor'],\n}\n\n/** Reconhece as colunas de auditoria pelo nome (sem diferenciar maiúsculas). */\nexport function detectAudit(columns: string[]): AuditColumns {\n  const out: AuditColumns = {}\n  for (const key of Object.keys(CANDIDATES) as Array<keyof AuditColumns>) {\n    for (const cand of CANDIDATES[key]) {\n      const found = columns.find(c => c.toLowerCase() === cand)\n      if (found) { out[key] = found; break }\n    }\n  }\n  return out\n}\n\n/** Limpa o que veio do banco/da tela. null = nada configurado (vale o reconhecimento pelo nome). */\nexport function cleanAuditConfig(raw: unknown): AuditConfig | null {\n  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null\n  const r = raw as Record<string, unknown>\n  const cfg: AuditConfig = {}\n  if (r.disabled === true) cfg.disabled = true\n  for (const k of ['createdAt', 'createdBy', 'updatedAt', 'updatedBy'] as const) {\n    const v = ident(r[k])\n    if (v) cfg[k] = v\n  }\n  const by = r.by as any\n  if (by && typeof by === 'object' && (by.source === 'user.email' || by.source === 'user.name' || by.source === 'user.attr')) {\n    const attr = ident(by.attr)\n    if (by.source !== 'user.attr') cfg.by = { source: by.source }\n    else if (attr) cfg.by = { source: 'user.attr', attr }\n  }\n  return Object.keys(cfg).length ? cfg : null\n}\n\nexport interface EffectiveAudit {\n  columns: AuditColumns\n  by: { source: RlsSource; attr?: string }\n}\n\n/**\n * O que vale numa tabela: o salvo pelo dev, ou o reconhecido pelo nome. Só entram colunas que existem de verdade na tabela\n * (uma coluna salva que foi removida do banco é ignorada, em vez de quebrar a gravação).\n */\nexport function effectiveAudit(saved: AuditConfig | null | undefined, tableColumns: string[]): EffectiveAudit | null {\n  if (saved?.disabled) return null\n  const exists = (c?: string) => (c ? tableColumns.find(x => x.toLowerCase() === c.toLowerCase()) : undefined)\n  const hasSaved = !!saved && (saved.createdAt || saved.createdBy || saved.updatedAt || saved.updatedBy)\n  const picked: AuditColumns = hasSaved\n    ? {\n        createdAt: exists(saved!.createdAt), createdBy: exists(saved!.createdBy),\n        updatedAt: exists(saved!.updatedAt), updatedBy: exists(saved!.updatedBy),\n      }\n    : detectAudit(tableColumns)\n  const columns: AuditColumns = {}\n  for (const k of ['createdAt', 'createdBy', 'updatedAt', 'updatedBy'] as const) if (picked[k]) columns[k] = picked[k]\n  if (Object.keys(columns).length === 0) return null\n  return { columns, by: saved?.by || DEFAULT_AUDIT_BY }\n}\n\n/** Colunas do cadastro do usuário que a auditoria usa (o login as grava na sessão assinada). */\nexport function auditAttrColumn(by: { source: RlsSource; attr?: string } | undefined): string | null {\n  return by?.source === 'user.attr' && by.attr ? by.attr : null\n}\n\n// ── SQL para o desenvolvedor aplicar no banco (PostgreSQL) ───────────────────────\n\nconst q = (s: string) => '\"' + s.replace(/\"/g, '\"\"') + '\"'\n\n/**\n * Script que cria as colunas de auditoria que faltam na tabela (e o gatilho que cuida das datas em qualquer caminho de\n * gravação). O MetaBuilder não altera o banco do cliente: quem aplica é o desenvolvedor.\n * `authTable` é a tabela de login, referenciada por `criado_por`/`atualizado_por`.\n */\nexport function auditSql(opts: { table: string; schema?: string; authTable?: string; authKey?: string; existing?: string[]; names?: AuditColumns }): string {\n  // sem esquema, os nomes saem sem prefixo: valem no esquema padrão da conexão (o nome \"crm\" do Studio é o do banco, não necessariamente o esquema)\n  const schema = opts.schema || ''\n  const qual = (name: string) => (schema ? `${q(schema)}.${q(name)}` : q(name))\n  const names: Required<AuditColumns> = {\n    createdAt: opts.names?.createdAt || 'criado_em',\n    createdBy: opts.names?.createdBy || 'criado_por',\n    updatedAt: opts.names?.updatedAt || 'atualizado_em',\n    updatedBy: opts.names?.updatedBy || 'atualizado_por',\n  }\n  const has = (c: string) => (opts.existing || []).some(x => x.toLowerCase() === c.toLowerCase())\n  const target = qual(opts.table)\n  const ref = opts.authTable ? ` REFERENCES ${qual(opts.authTable)}(${q(opts.authKey || 'id')}) ON DELETE SET NULL` : ''\n  const lines: string[] = []\n  if (!has(names.createdAt)) lines.push(`ALTER TABLE ${target} ADD COLUMN IF NOT EXISTS ${q(names.createdAt)} timestamptz NOT NULL DEFAULT now();`)\n  if (!has(names.createdBy)) lines.push(`ALTER TABLE ${target} ADD COLUMN IF NOT EXISTS ${q(names.createdBy)} uuid${ref};`)\n  if (!has(names.updatedAt)) lines.push(`ALTER TABLE ${target} ADD COLUMN IF NOT EXISTS ${q(names.updatedAt)} timestamptz NOT NULL DEFAULT now();`)\n  if (!has(names.updatedBy)) lines.push(`ALTER TABLE ${target} ADD COLUMN IF NOT EXISTS ${q(names.updatedBy)} uuid${ref};`)\n  const fn = qual(`mb_auditoria_${opts.table.replace(/[^A-Za-z0-9_]/g, '_')}`)\n  return [\n    `-- Auditoria da tabela ${opts.table} (PostgreSQL). Aplique no banco do cliente.`,\n    ...lines,\n    '',\n    `CREATE OR REPLACE FUNCTION ${fn}() RETURNS trigger LANGUAGE plpgsql AS $$`,\n    'BEGIN',\n    `  NEW.${q(names.updatedAt)} := now();`,\n    `  NEW.${q(names.createdAt)} := OLD.${q(names.createdAt)};`,\n    `  NEW.${q(names.createdBy)} := COALESCE(OLD.${q(names.createdBy)}, NEW.${q(names.createdBy)});`,\n    '  RETURN NEW;',\n    'END $$;',\n    '',\n    `DROP TRIGGER IF EXISTS mb_auditoria_update ON ${target};`,\n    `CREATE TRIGGER mb_auditoria_update BEFORE UPDATE ON ${target} FOR EACH ROW EXECUTE FUNCTION ${fn}();`,\n  ].join('\\n')\n}\n",
  "lib/rowPolicy/sqlPolicy.js": "/**\n * Acesso a dados do usuário final, aplicado AQUI, dentro do Agente (que fala com o banco do cliente).\n *\n * O servidor do MetaBuilder confere quem é o usuário (sessão assinada), resolve as políticas por tabela (permissões de\n * criar/editar/excluir e acesso por linha) e envia o resultado DENTRO do comando assinado, em `payload.access`. O navegador\n * não consegue tirar nem alterar isso. Este arquivo faz valer a política em qualquer SQL que o usuário final mande, sem\n * depender do formato do SQL:\n *\n *   - leitura: cada referência à tabela (FROM/JOIN) vira uma subconsulta filtrada: `FROM (SELECT * FROM \"t\" WHERE <regra>) AS \"t\"`;\n *   - toda outra forma de citar uma tabela com política (vírgula, função, comentário...) é RECUSADA (falha fechada);\n *   - gravação estruturada (insert/update/delete): confere a permissão, os valores gravados e as linhas atingidas;\n *   - SQL de dados livre (execute_custom): UPDATE/DELETE recebem a regra no WHERE; INSERT em tabela com política é recusado.\n *\n * Não depende de nada do Agente (só texto), para ser testado sozinho. O formato de `access`:\n *   { policies: [{ table, deny?: true, conds: [{ column, op: 'eq'|'in'|'related', values: string[], related?: { table, key, column } }] }],\n *     flags:    { <tabela em minúsculas>: { create?: boolean, update?: boolean, delete?: boolean } } }\n */\n\nclass PolicyError extends Error {\n  constructor(message) { super(message); this.name = 'PolicyError'; }\n}\n\nconst IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;\nconst MAX_VALUES = 100;\n\n// ── Valores e identificadores ────────────────────────────────────────────────────\n\nfunction quoteIdent(name) {\n  if (typeof name !== 'string' || !IDENT.test(name)) throw new PolicyError('Nome inválido na política de acesso.');\n  return `\"${name}\"`;\n}\n\n/** Texto SQL entre aspas simples. Postgres: com barra invertida usa E'...' (vale com qualquer configuração do servidor). */\nfunction literal(value, dbType) {\n  const s = String(value);\n  if (s.includes('\\0')) throw new PolicyError('Valor inválido na política de acesso.');\n  const body = s.replace(/'/g, \"''\");\n  if (dbType !== 'oracle' && s.includes('\\\\')) return `E'${body.replace(/\\\\/g, '\\\\\\\\')}'`;\n  return `'${body}'`;\n}\n\n/** Condição de UMA regra sobre a coluna (qualificada, se informado o qualificador). */\nfunction condSql(cond, qualifier, dbType) {\n  const col = qualifier ? `${quoteIdent(qualifier)}.${quoteIdent(cond.column)}` : quoteIdent(cond.column);\n  const values = (cond.values || []).slice(0, MAX_VALUES);\n  if (values.length === 0) return '1 = 0';\n  if (cond.op === 'related') {\n    const r = cond.related || {};\n    const inner = `SELECT ${quoteIdent(r.key)} FROM ${quoteIdent(r.table)} WHERE ${quoteIdent(r.column)} = ${literal(values[0], dbType)}`;\n    return `${col} IN (${inner})`;\n  }\n  if (cond.op === 'in') return `${col} IN (${values.map(v => literal(v, dbType)).join(', ')})`;\n  return `${col} = ${literal(values[0], dbType)}`;\n}\n\n/** Todas as regras da tabela juntas (E). Tabela negada = nenhuma linha. */\nfunction policySql(policy, qualifier, dbType) {\n  if (!policy || policy.deny) return '1 = 0';\n  const parts = (policy.conds || []).map(c => condSql(c, qualifier, dbType));\n  return parts.length ? parts.map(p => `(${p})`).join(' AND ') : '1 = 1';\n}\n\nfunction policyMap(access) {\n  const map = new Map();\n  for (const p of (access && access.policies) || []) {\n    if (p && typeof p.table === 'string') map.set(p.table.toLowerCase(), p);\n  }\n  return map;\n}\n\n// ── Leitura do SQL em partes ─────────────────────────────────────────────────────\n\n/** tipos: ws, word (minúsculo em `v`), ident (\"...\" sem aspas em `v`), str, num, param, punct, raw (texto já pronto) */\nfunction tokenize(sql) {\n  const toks = [];\n  const n = sql.length;\n  let i = 0;\n  while (i < n) {\n    const c = sql[i];\n    if (/\\s/.test(c)) {\n      let j = i + 1;\n      while (j < n && /\\s/.test(sql[j])) j++;\n      toks.push({ k: 'ws', v: ' ', raw: sql.slice(i, j) });\n      i = j;\n    } else if ((c === '-' && sql[i + 1] === '-') || (c === '/' && sql[i + 1] === '*')) {\n      throw new PolicyError('Comentário em SQL não é permitido.');\n    } else if (c === \"'\") {\n      // E'...' aceita barra invertida como escape; o resto só dobra a aspa\n      const prev = toks[toks.length - 1];\n      const eMode = !!prev && prev.k === 'word' && prev.v === 'e' && prev.raw.length === 1;\n      let j = i + 1;\n      let closed = false;\n      while (j < n) {\n        if (eMode && sql[j] === '\\\\') { j += 2; continue; }\n        if (sql[j] === \"'\") {\n          if (sql[j + 1] === \"'\") { j += 2; continue; }\n          closed = true; j++; break;\n        }\n        j++;\n      }\n      if (!closed) throw new PolicyError('Texto SQL sem fechamento.');\n      toks.push({ k: 'str', v: sql.slice(i, j), raw: sql.slice(i, j) });\n      i = j;\n    } else if (c === '\"') {\n      let j = i + 1;\n      let name = '';\n      let closed = false;\n      while (j < n) {\n        if (sql[j] === '\"') {\n          if (sql[j + 1] === '\"') { name += '\"'; j += 2; continue; }\n          closed = true; j++; break;\n        }\n        name += sql[j++];\n      }\n      if (!closed) throw new PolicyError('Identificador SQL sem fechamento.');\n      toks.push({ k: 'ident', v: name, raw: sql.slice(i, j) });\n      i = j;\n    } else if (c === '$') {\n      let j = i + 1;\n      if (/[0-9]/.test(sql[j] || '')) {\n        while (j < n && /[0-9]/.test(sql[j])) j++;\n        toks.push({ k: 'param', v: sql.slice(i, j), raw: sql.slice(i, j) });\n        i = j;\n      } else {\n        // $$...$$ e $tag$...$tag$ escondem texto do leitor: não aceitos\n        throw new PolicyError('Texto entre cifrões não é permitido.');\n      }\n    } else if (/[A-Za-z_À-￿]/.test(c)) {\n      let j = i + 1;\n      while (j < n && /[A-Za-z0-9_$À-￿]/.test(sql[j])) j++;\n      const raw = sql.slice(i, j);\n      toks.push({ k: 'word', v: raw.toLowerCase(), raw });\n      i = j;\n    } else if (/[0-9]/.test(c)) {\n      let j = i + 1;\n      while (j < n && /[0-9.eE]/.test(sql[j])) j++;\n      toks.push({ k: 'num', v: sql.slice(i, j), raw: sql.slice(i, j) });\n      i = j;\n    } else {\n      toks.push({ k: 'punct', v: c, raw: c });\n      i++;\n    }\n  }\n  return toks;\n}\n\nconst nameOf = t => (t.k === 'word' || t.k === 'ident' ? t.v.toLowerCase() : null);\nconst isWord = (t, w) => !!t && t.k === 'word' && t.v === w;\nconst isPunct = (t, p) => !!t && t.k === 'punct' && t.v === p;\n\n/** Palavras que NÃO são apelido de tabela. */\nconst RESERVED = new Set([\n  'where', 'group', 'order', 'limit', 'offset', 'fetch', 'having', 'union', 'intersect', 'except', 'minus', 'join', 'inner',\n  'left', 'right', 'full', 'cross', 'natural', 'on', 'using', 'window', 'for', 'returning', 'set', 'values', 'select',\n  'lateral', 'tablesample', 'and', 'or', 'not', 'with', 'connect', 'start', 'as', '__where_placeholder__',\n]);\n\n/** Funções cujo `FROM` interno não é uma tabela. */\nconst FROM_FUNCTIONS = new Set(['extract', 'substring', 'trim', 'overlay', 'position']);\n\n/** Posição do próximo token que não é espaço (-1 se não houver). */\nfunction sig(toks, from) {\n  for (let i = from; i < toks.length; i++) if (toks[i].k !== 'ws') return i;\n  return -1;\n}\nfunction sigBack(toks, from) {\n  for (let i = from; i >= 0; i--) if (toks[i].k !== 'ws') return i;\n  return -1;\n}\n\n/**\n * Lê o nome de uma tabela a partir de `start` (um token que não é espaço): `nome` ou `esquema.nome`.\n * Devolve { end (último token do nome), last (nome da tabela, minúsculo), text (como estava escrito) } ou null.\n */\nfunction readRelation(toks, start) {\n  const first = toks[start];\n  if (!first || (first.k !== 'word' && first.k !== 'ident')) return null;\n  let end = start;\n  let last = nameOf(first);\n  let text = first.raw;\n  for (;;) {\n    const d = sig(toks, end + 1);\n    if (d < 0 || !isPunct(toks[d], '.')) break;\n    const nx = sig(toks, d + 1);\n    if (nx < 0 || (toks[nx].k !== 'word' && toks[nx].k !== 'ident')) break;\n    text += '.' + toks[nx].raw;\n    last = nameOf(toks[nx]);\n    end = nx;\n  }\n  return { end, last, text };\n}\n\n/** Apelido logo depois da tabela: `AS x`, `\"x\"` ou `x` (se x não for palavra reservada). Devolve { end, text, name } ou null. */\nfunction readAlias(toks, after) {\n  const a = sig(toks, after + 1);\n  if (a < 0) return null;\n  const t = toks[a];\n  if (isWord(t, 'as')) {\n    const b = sig(toks, a + 1);\n    if (b >= 0 && (toks[b].k === 'word' || toks[b].k === 'ident')) return { end: b, text: sliceRaw(toks, a, b), name: toks[b].v, explicitAs: true };\n    return null;\n  }\n  if (t.k === 'ident') return { end: a, text: t.raw, name: t.v, explicitAs: false };\n  if (t.k === 'word' && !RESERVED.has(t.v)) return { end: a, text: t.raw, name: t.v, explicitAs: false };\n  return null;\n}\n\nconst sliceRaw = (toks, a, b) => toks.slice(a, b + 1).map(t => t.raw).join('');\n\n// ── Leitura (SELECT): cada tabela com política vira subconsulta filtrada ─────────\n\n/**\n * Reescreve os tokens de UMA consulta. `skipTo` permite pular o início (usado pelo UPDATE/DELETE, cujo alvo é tratado à parte).\n */\nfunction rewriteTokens(toks, policies, dbType, from = 0) {\n  const out = [];\n  const parenFn = []; // pilha: o parêntese aberto pertence a EXTRACT/SUBSTRING/...?\n  for (let i = 0; i < from; i++) out.push(toks[i].raw);\n\n  for (let i = from; i < toks.length; i++) {\n    const t = toks[i];\n\n    if (isPunct(t, '(')) {\n      const p = sigBack(toks, i - 1);\n      parenFn.push(p >= 0 && toks[p].k === 'word' && FROM_FUNCTIONS.has(toks[p].v));\n      out.push(t.raw);\n      continue;\n    }\n    if (isPunct(t, ')')) { parenFn.pop(); out.push(t.raw); continue; }\n\n    const isFrom = isWord(t, 'from') || isWord(t, 'join') || isWord(t, 'using');\n    if (isFrom) {\n      const p = sigBack(toks, i - 1);\n      const inFn = isWord(t, 'from') && parenFn.length > 0 && parenFn[parenFn.length - 1];\n      const distinct = isWord(t, 'from') && p >= 0 && isWord(toks[p], 'distinct');\n      if (!inFn && !distinct) {\n        let r = sig(toks, i + 1);\n        // palavras que antecedem o nome sem serem o nome\n        while (r >= 0 && (isWord(toks[r], 'only') || isWord(toks[r], 'lateral'))) r = sig(toks, r + 1);\n        if (r >= 0 && toks[r].k !== 'punct') {\n          const rel = readRelation(toks, r);\n          if (rel && policies.has(rel.last)) {\n            const policy = policies.get(rel.last);\n            const alias = readAlias(toks, rel.end);\n            const sub = `(SELECT * FROM ${rel.text} WHERE ${policySql(policy, null, dbType)})`;\n            out.push(sliceRaw(toks, i, i)); // a palavra FROM/JOIN\n            out.push(toks.slice(i + 1, r).map(x => x.raw).join('')); // espaços (e ONLY/LATERAL) entre a palavra e o nome\n            if (alias) {\n              out.push(`${sub} ${alias.text}`);\n              i = alias.end;\n            } else {\n              out.push(dbType === 'oracle' ? `${sub} ${quoteIdent(rel.last)}` : `${sub} AS ${quoteIdent(rel.last)}`);\n              i = rel.end;\n            }\n            continue;\n          }\n        }\n      }\n      out.push(t.raw);\n      continue;\n    }\n\n    // Qualquer outra citação de uma tabela com política precisa estar numa forma segura\n    const nm = nameOf(t);\n    if (nm && policies.has(nm) && t.k !== 'raw') {\n      const nx = sig(toks, i + 1);\n      const pv = sigBack(toks, i - 1);\n      const qualifier = nx >= 0 && isPunct(toks[nx], '.');\n      const aliasDef = pv >= 0 && isWord(toks[pv], 'as');\n      const afterDot = pv >= 0 && isPunct(toks[pv], '.');\n      if (!qualifier && !aliasDef && !afterDot) {\n        throw new PolicyError(`A tabela \"${nm}\" tem acesso restrito e foi citada numa forma não permitida.`);\n      }\n    }\n    out.push(t.raw);\n  }\n  return out.join('');\n}\n\n/** SELECT final montado pelo Agente (ou enviado pela tela): devolve o SQL com as políticas aplicadas. */\nfunction applyToSelect(sql, access, opts = {}) {\n  const policies = policyMap(access);\n  if (policies.size === 0) return sql;\n  const toks = tokenize(String(sql));\n  const stmts = splitStatements(toks);\n  if (stmts.length > 1) throw new PolicyError('Mais de um comando SQL não é permitido.');\n  return rewriteTokens(stmts[0] || [], policies, opts.dbType === 'oracle' ? 'oracle' : 'postgres');\n}\n\n// ── SQL de dados livre (execute_custom) ──────────────────────────────────────────\n\nconst FLAG_OF = { insert: 'create', update: 'update', delete: 'delete' };\n\nfunction flagAllowed(access, table, kind) {\n  const f = access && access.flags && access.flags[String(table).toLowerCase()];\n  return !(f && f[kind] === false);\n}\n\nconst FLAG_MESSAGE = {\n  create: 'Esta tabela não permite criar registros.',\n  update: 'Esta tabela não permite editar registros.',\n  delete: 'Esta tabela não permite excluir registros.',\n};\n\n/** Divide em comandos nos `;` fora de parênteses (os textos já são tokens próprios, então um `;` dentro deles não conta). */\nfunction splitStatements(toks) {\n  const stmts = [];\n  let cur = [];\n  let depth = 0;\n  for (const t of toks) {\n    if (isPunct(t, '(')) depth++;\n    if (isPunct(t, ')')) depth--;\n    if (isPunct(t, ';') && depth === 0) { stmts.push(cur); cur = []; continue; }\n    cur.push(t);\n  }\n  stmts.push(cur);\n  return stmts.filter(s => s.some(t => t.k !== 'ws'));\n}\n\n/** Índice (no vetor) do primeiro token de palavra `w` fora de parênteses, a partir de `from`; -1 se não houver. */\nfunction topLevelWord(toks, w, from) {\n  let depth = 0;\n  for (let i = from; i < toks.length; i++) {\n    if (isPunct(toks[i], '(')) depth++;\n    else if (isPunct(toks[i], ')')) depth--;\n    else if (depth === 0 && isWord(toks[i], w)) return i;\n  }\n  return -1;\n}\n\nfunction guardStatement(toks, access, policies, dbType) {\n  const f = sig(toks, 0);\n  const head = toks[f].v;\n  if (head === 'select' || head === 'values' || head === 'table') return rewriteTokens(toks, policies, dbType);\n\n  if (head === 'with') {\n    // CTE: só leitura (qualquer comando de gravação dentro dela é recusado)\n    if (toks.some(t => t.k === 'word' && (t.v === 'insert' || t.v === 'update' || t.v === 'delete'))) {\n      throw new PolicyError('Comando de gravação dentro de WITH não é permitido.');\n    }\n    return rewriteTokens(toks, policies, dbType);\n  }\n\n  if (head === 'insert') {\n    const into = sig(toks, f + 1);\n    const r = into >= 0 && isWord(toks[into], 'into') ? sig(toks, into + 1) : -1;\n    const rel = r >= 0 ? readRelation(toks, r) : null;\n    if (!rel) throw new PolicyError('Comando INSERT não reconhecido.');\n    if (!flagAllowed(access, rel.last, 'create')) throw new PolicyError(FLAG_MESSAGE.create);\n    if (policies.has(rel.last)) throw new PolicyError(`A tabela \"${rel.last}\" tem acesso restrito: grave pelo cadastro, não por SQL livre.`);\n    return rewriteTokens(toks, policies, dbType, rel.end + 1);\n  }\n\n  if (head === 'delete' || head === 'update') {\n    let r;\n    if (head === 'delete') {\n      const fr = sig(toks, f + 1);\n      if (fr < 0 || !isWord(toks[fr], 'from')) throw new PolicyError('Comando DELETE não reconhecido.');\n      r = sig(toks, fr + 1);\n    } else {\n      r = sig(toks, f + 1);\n    }\n    const rel = r >= 0 ? readRelation(toks, r) : null;\n    if (!rel) throw new PolicyError(`Comando ${head.toUpperCase()} não reconhecido.`);\n    const kind = FLAG_OF[head];\n    if (!flagAllowed(access, rel.last, kind)) throw new PolicyError(FLAG_MESSAGE[kind]);\n\n    const alias = readAlias(toks, rel.end);\n    const restFrom = (alias ? alias.end : rel.end) + 1;\n\n    const policy = policies.get(rel.last);\n    if (!policy) return rewriteTokens(toks, policies, dbType, restFrom);\n\n    // a regra vai no WHERE do próprio comando: ela só alcança as linhas que o usuário pode ver\n    const qualifier = alias ? alias.name : rel.last;\n    const cond = policySql(policy, qualifier, dbType);\n    const where = topLevelWord(toks, 'where', restFrom);\n    const ret = topLevelWord(toks, 'returning', where >= 0 ? where : restFrom);\n    const retAt = ret >= 0 ? ret : toks.length;\n    const edited = [];\n    if (where >= 0) {\n      for (let i = 0; i <= where; i++) edited.push(toks[i]);\n      edited.push({ k: 'raw', v: '(', raw: ' (' });\n      for (let i = where + 1; i < retAt; i++) edited.push(toks[i]);\n      edited.push({ k: 'raw', v: ')', raw: `) AND (${cond}) ` });\n    } else {\n      for (let i = 0; i < retAt; i++) edited.push(toks[i]);\n      edited.push({ k: 'raw', v: 'where', raw: ` WHERE ${cond} ` });\n    }\n    for (let i = retAt; i < toks.length; i++) edited.push(toks[i]);\n    return rewriteTokens(edited, policies, dbType, restFrom);\n  }\n\n  throw new PolicyError('Comando SQL não permitido.');\n}\n\n/** SQL livre de usuário final (um ou vários comandos de dados separados por `;`). */\nfunction guardCustom(sql, access, opts = {}) {\n  const dbType = opts.dbType === 'oracle' ? 'oracle' : 'postgres';\n  const policies = policyMap(access);\n  const toks = tokenize(String(sql));\n  const stmts = splitStatements(toks);\n  if (stmts.length === 0) throw new PolicyError('SQL vazio.');\n  return stmts.map(s => guardStatement(s, access, policies, dbType).trim()).join('; ');\n}\n\n// ── Gravação estruturada (insert / update / delete) ──────────────────────────────\n\nconst keyIn = (data, column) => Object.keys(data).find(k => k.toLowerCase() === String(column).toLowerCase());\n\n/**\n * Auditoria (quem/quando): descarta o que a tela mandou nas colunas de auditoria e põe os valores do servidor. No insert\n * preenche criado_* e atualizado_*; no update só atualizado_* (criado_* nunca muda). `*_por` fica vazio se o usuário não tem\n * o dado configurado (access.audit[tabela].actor).\n */\nfunction applyAudit(access, table, action, data) {\n  const a = access && access.audit && access.audit[table];\n  if (!a) return data;\n  const out = data ? { ...data } : {};\n  const cols = [a.createdAt, a.createdBy, a.updatedAt, a.updatedBy].filter(Boolean).map(c => String(c).toLowerCase());\n  for (const k of Object.keys(out)) if (cols.includes(k.toLowerCase())) delete out[k];\n  const now = new Date().toISOString();\n  const actor = a.actor === undefined || a.actor === null || a.actor === '' ? null : String(a.actor);\n  if (action === 'insert') {\n    if (a.createdAt) out[a.createdAt] = now;\n    if (a.createdBy && actor !== null) out[a.createdBy] = actor;\n  }\n  if (a.updatedAt) out[a.updatedAt] = now;\n  if (a.updatedBy && actor !== null) out[a.updatedBy] = actor;\n  return out;\n}\n\n/**\n * Confere uma gravação estruturada e devolve os dados a gravar (no insert, completa com o valor da regra o que faltou).\n * `query(sql)` executa um SELECT e devolve as linhas (usado para a regra por tabela relacionada e para conferir as linhas atingidas).\n * `checkRows: false` pula a conferência das linhas atingidas (quem chama garante isso por outro meio, ex.: guardCustom no WHERE).\n */\nasync function enforceWrite({ access, action, table, data, idColumn, idValue, dbType, query, checkRows = true }) {\n  const t = String(table || '').toLowerCase();\n  const kind = FLAG_OF[action];\n  if (!kind) return data;\n  if (!flagAllowed(access, t, kind)) throw new PolicyError(FLAG_MESSAGE[kind]);\n\n  // auditoria primeiro: as colunas de quem/quando já entram com os valores do servidor, e a regra por linha confere o resultado final\n  const working = action === 'insert' || action === 'update' ? applyAudit(access, t, action, data) : data;\n\n  const policy = policyMap(access).get(t);\n  if (!policy) return working;\n  if (policy.deny) throw new PolicyError('Você não tem acesso aos registros desta tabela.');\n  const db = dbType === 'oracle' ? 'oracle' : 'postgres';\n  const out = working ? { ...working } : (action === 'insert' ? {} : working);\n\n  // os valores gravados precisam obedecer à regra (senão o usuário criaria/passaria para outro dono uma linha que não enxerga)\n  if (action === 'insert' || action === 'update') {\n    for (const c of policy.conds || []) {\n      const key = keyIn(out || {}, c.column);\n      if (key === undefined) {\n        // coluna ausente no insert: a regra \"igual\" (ou lista de um valor só) preenche; as demais ficam como o banco definir\n        if (action === 'insert' && c.op !== 'related' && (c.values || []).length === 1) {\n          out[c.column] = c.values[0];\n        }\n        continue;\n      }\n      const v = out[key];\n      if (v === null || v === undefined || v === '') {\n        throw new PolicyError(`O campo \"${c.column}\" é controlado pelo seu acesso e não pode ficar vazio.`);\n      }\n      if (c.op === 'related') {\n        const r = c.related || {};\n        const rows = await query(`SELECT 1 AS ok FROM ${quoteIdent(r.table)} WHERE ${quoteIdent(r.key)} = ${literal(v, db)} AND ${quoteIdent(r.column)} = ${literal((c.values || [])[0], db)}`);\n        if (!rows || rows.length === 0) throw new PolicyError(`O valor de \"${c.column}\" está fora do seu acesso.`);\n      } else if (!(c.values || []).map(String).includes(String(v))) {\n        throw new PolicyError(`O valor de \"${c.column}\" está fora do seu acesso.`);\n      }\n    }\n  }\n\n  // update/delete: TODAS as linhas que o comando alcança precisam estar dentro da regra\n  if ((action === 'update' || action === 'delete') && checkRows) {\n    const idc = quoteIdent(String(idColumn || 'id'));\n    const all = await query(`SELECT COUNT(*) AS c FROM ${quoteIdent(String(table))} WHERE ${idc} = ${literal(idValue, db)}`);\n    const mine = await query(`SELECT COUNT(*) AS c FROM ${quoteIdent(String(table))} WHERE ${idc} = ${literal(idValue, db)} AND ${policySql(policy, null, db)}`);\n    const n = rows => Number((rows && rows[0] && (rows[0].c ?? rows[0].C)) || 0);\n    if (n(all) !== n(mine) || n(mine) === 0) throw new PolicyError('Registro não encontrado ou fora do seu acesso.');\n  }\n  return out;\n}\n\nmodule.exports = { applyAudit, PolicyError, tokenize, applyToSelect, guardCustom, enforceWrite, policySql, condSql, literal, flagAllowed };\n",
  "lib/rowPolicy/sqlPolicy.d.ts": "// Tipos do módulo cli/sqlPolicy.js (JavaScript puro, sem dependências). Este arquivo só é copiado, junto com o .js, para dentro do\n// app exportado (lib/rowPolicy/): lá o TypeScript precisa de tipos para importar o módulo. Veja scripts/gen-bi-runtime.mjs.\n\nexport class PolicyError extends Error {}\n\nexport interface SqlAccess {\n  policies: Array<{ table: string; deny?: boolean; conds: Array<{ column: string; op: string; values: string[]; related?: { table: string; key: string; column: string } }> }>\n  flags: Record<string, { create?: boolean; update?: boolean; delete?: boolean }>\n  audit?: Record<string, { createdAt?: string; createdBy?: string; updatedAt?: string; updatedBy?: string; actor?: string | null }>\n}\n\nexport function applyToSelect(sql: string, access: SqlAccess, opts?: { dbType?: string }): string\nexport function guardCustom(sql: string, access: SqlAccess, opts?: { dbType?: string }): string\nexport function enforceWrite(args: {\n  access: SqlAccess\n  action: 'insert' | 'update' | 'delete'\n  table: string\n  data?: Record<string, any>\n  idColumn?: string\n  idValue?: any\n  dbType?: string\n  query: (sql: string) => Promise<any[]>\n  /** false = não confere as linhas atingidas (quem chama garante pelo WHERE) */\n  checkRows?: boolean\n}): Promise<Record<string, any> | undefined>\nexport function applyAudit(access: SqlAccess, table: string, action: 'insert' | 'update', data?: Record<string, any>): Record<string, any> | undefined\nexport function flagAllowed(access: SqlAccess, table: string, kind: 'create' | 'update' | 'delete'): boolean\nexport function policySql(policy: any, qualifier: string | null, dbType?: string): string\nexport function condSql(cond: any, qualifier: string | null, dbType?: string): string\nexport function literal(value: unknown, dbType?: string): string\nexport function tokenize(sql: string): any[]\n",
  "lib/bi/access.ts": "/**\n * Acesso por linha (RLS) do painel de BI.\n *\n * O desenvolvedor cadastra regras do tipo \"só mostre as linhas em que PEDIDOS.VENDEDOR_ID = valor do usuário logado\".\n * Cada regra vira uma condição comum do widget (o planejador cuida de JOINs, tipos e escape), então vale para o\n * indicador, o drill, \"ver registros\" e o filtro cruzado sem código especial.\n *\n * Falha fechada: sem usuário, sem o atributo que a regra pede ou numa tabela sem relação com a coluna da regra, o\n * widget NÃO mostra dados (nunca cai em \"mostrar tudo\").\n */\nimport type { BiWidgetCondition } from './widget'\n\nexport type RlsSource = 'user.email' | 'user.name' | 'user.attr'\n\nexport interface RlsBypass {\n  source: RlsSource\n  /** coluna da tabela de usuários (quando source = 'user.attr') */\n  attr?: string\n  /** quem tiver um destes valores não sofre a regra (ex.: perfil \"admin\") */\n  values: string[]\n}\n\nexport interface RlsRule {\n  id: string\n  /** coluna que limita as linhas (\"tabela.coluna\") */\n  field: string\n  /** 'eq' = igual ao valor do usuário; 'in' = o valor do usuário é uma lista separada por vírgulas */\n  op: 'eq' | 'in'\n  source: RlsSource\n  attr?: string\n  bypass?: RlsBypass\n}\n\n/** Quem está vendo o painel (vem da sessão; nunca do navegador no app exportado). */\nexport interface BiViewer {\n  email?: string | null\n  name?: string | null\n  attrs?: Record<string, unknown> | null\n}\n\nexport type AccessDenied =\n  | { code: 'no_viewer' }\n  | { code: 'missing_value'; detail: string }\n\nexport interface AccessResult {\n  conditions: BiWidgetCondition[]\n  denied?: AccessDenied\n}\n\nconst SOURCES: RlsSource[] = ['user.email', 'user.name', 'user.attr']\nconst MAX_RULES = 20\nconst MAX_BYPASS_VALUES = 50\n\nconst text = (v: unknown, max = 200): string => (typeof v === 'string' ? v.trim().slice(0, max) : '')\n\n/** Valor do usuário para uma fonte; null quando não existe ou está vazio. */\nexport function viewerValue(viewer: BiViewer | null | undefined, source: RlsSource, attr?: string): string | null {\n  if (!viewer) return null\n  let raw: unknown\n  if (source === 'user.email') raw = viewer.email\n  else if (source === 'user.name') raw = viewer.name\n  else if (attr && viewer.attrs) {\n    const key = Object.keys(viewer.attrs).find(k => k.toLowerCase() === attr.toLowerCase())\n    raw = key ? viewer.attrs[key] : undefined\n  }\n  if (raw === null || raw === undefined) return null\n  const s = String(raw).trim()\n  return s === '' ? null : s\n}\n\n/** Limpa as regras vindas de uma configuração salva (descarta o que está incompleto). */\nexport function cleanRlsRules(raw: unknown): RlsRule[] {\n  if (!Array.isArray(raw)) return []\n  const out: RlsRule[] = []\n  for (const r of raw.slice(0, MAX_RULES)) {\n    if (!r || typeof r !== 'object') continue\n    const field = text((r as any).field)\n    const source = (r as any).source as RlsSource\n    if (!field || !SOURCES.includes(source)) continue\n    const attr = text((r as any).attr)\n    if (source === 'user.attr' && !attr) continue\n    const rule: RlsRule = {\n      id: text((r as any).id, 60) || `rls_${out.length + 1}`,\n      field,\n      op: (r as any).op === 'in' ? 'in' : 'eq',\n      source,\n      ...(source === 'user.attr' ? { attr } : {}),\n    }\n    const b = (r as any).bypass\n    if (b && typeof b === 'object' && SOURCES.includes(b.source) && Array.isArray(b.values)) {\n      const values = b.values.map((v: unknown) => text(v)).filter(Boolean).slice(0, MAX_BYPASS_VALUES)\n      const bAttr = text(b.attr)\n      if (values.length > 0 && (b.source !== 'user.attr' || bAttr)) {\n        rule.bypass = { source: b.source, ...(b.source === 'user.attr' ? { attr: bAttr } : {}), values }\n      }\n    }\n    out.push(rule)\n  }\n  return out\n}\n\n/** O usuário está na lista de exceção da regra? (compara sem diferenciar maiúsculas) */\nfunction bypassed(rule: RlsRule, viewer: BiViewer | null | undefined): boolean {\n  if (!rule.bypass) return false\n  const v = viewerValue(viewer, rule.bypass.source, rule.bypass.attr)\n  return v !== null && rule.bypass.values.some(x => x.toLowerCase() === v.toLowerCase())\n}\n\n/** Condições que as regras impõem a este usuário (ou o motivo de negar o acesso). */\nexport function rlsAccess(rules: RlsRule[] | undefined, viewer: BiViewer | null | undefined): AccessResult {\n  const list = rules || []\n  if (list.length === 0) return { conditions: [] }\n  const conditions: BiWidgetCondition[] = []\n  for (const rule of list) {\n    // quem tem exceção na regra não sofre o filtro dela (e não precisa de atributo nenhum)\n    if (bypassed(rule, viewer)) continue\n    if (!viewer) return { conditions: [], denied: { code: 'no_viewer' } }\n    const value = viewerValue(viewer, rule.source, rule.attr)\n    if (value === null) {\n      return { conditions: [], denied: { code: 'missing_value', detail: rule.source === 'user.attr' ? rule.attr || '' : rule.source.replace('user.', '') } }\n    }\n    conditions.push({ field: rule.field, op: rule.op, value })\n  }\n  return { conditions }\n}\n\n/** Soma as condições do acesso às do widget. */\nexport function withAccess<W extends { conditions?: BiWidgetCondition[] }>(widget: W, access: AccessResult): W {\n  return access.conditions.length ? { ...widget, conditions: [...(widget.conditions || []), ...access.conditions] } : widget\n}\n\n/** Colunas da tabela de usuários que as regras consultam (o login as guarda na sessão). */\nexport function rlsAttrColumns(rules: RlsRule[] | undefined): string[] {\n  const cols = new Set<string>()\n  for (const r of rules || []) {\n    if (r.source === 'user.attr' && r.attr) cols.add(r.attr)\n    if (r.bypass?.source === 'user.attr' && r.bypass.attr) cols.add(r.bypass.attr)\n  }\n  return [...cols]\n}\n",
  "lib/bi/widget.ts": "/**\n * Esquema ÚNICO do widget de BI, no formato em que é gravado (analytics_config.widgets).\n *\n * Antes havia três descrições que divergiam: a do painel em execução (AnalyticsDashboard), a do Studio (types.ts)\n * e a do gerador do app exportado (ast.ts, em camelCase). Agora todas usam estes tipos; o gerador guarda o widget\n * original em `spec` e cada recurso novo é escrito uma vez só, aqui.\n */\nimport type { BiGroup } from './groups'\nimport type { RlsRule } from './access'\n\nexport type BiWidgetType = 'kpi' | 'bar' | 'pie' | 'line' | 'area' | 'gauge'\nexport type BiWidgetCalc = 'COUNT' | 'COUNT_DISTINCT' | 'SUM' | 'AVG' | 'MIN' | 'MAX'\nexport type BiWidgetWidth = 'full' | 'half' | 'third' | 'quarter'\nexport type BiPeriodMode = 'panel' | 'fixed' | 'own' | 'group'\n\n/** Filtro do widget com operador (campo = \"tabela.coluna\"). */\nexport interface BiWidgetCondition { field: string; op: string; value?: string; value2?: string }\n\nexport interface BiWidget {\n  id: string\n  title?: string\n  type: BiWidgetType | string\n  model_id?: string\n  model_name?: string\n  /** campo do valor (\"tabela.coluna\"), fórmula (quando use_formula) ou vazio = toda a tabela */\n  field?: string\n  field_id?: string\n  calc?: BiWidgetCalc | string\n  /** agrupar por (\"tabela.coluna\") */\n  group_by?: string\n  width?: BiWidgetWidth | string\n  /** JOINs configurados manualmente (legado) */\n  joins?: any[]\n\n  // medidor\n  gauge_min?: number\n  gauge_max?: number\n  gauge_target?: number\n  gauge_start?: number\n  gauge_end?: number\n\n  // valor e agrupamento\n  use_formula?: boolean\n  formula_tokens?: any[]\n  date_granularity?: 'day' | 'week' | 'month' | 'quarter' | 'year' | string\n  sort_by?: 'value_desc' | 'value_asc' | 'label_asc' | 'label_desc' | string\n  limit_top_n?: number\n\n  // aparência\n  format?: string\n  decimals?: number\n  currency?: string\n  color?: string\n  show_labels?: boolean\n  highlight_max?: boolean\n  orientation?: 'vertical' | 'horizontal' | string\n  stacked?: boolean\n\n  // Fase 2\n  conditions?: BiWidgetCondition[]\n  /** segunda dimensão (série) para barras, linhas e área */\n  series_by?: string\n  /** métrica derivada: valor = (calc/field) ÷ (divide_by.calc/divide_by.field) */\n  divide_by?: { calc: string; field?: string }\n  /** campo de data que recebe o filtro de período */\n  period_field?: string\n  period_mode?: BiPeriodMode\n  period_fixed?: string\n  /** agrupamento a que o widget pertence (id em analytics_config.groups) */\n  group_id?: string\n  /** caminho de relação escolhido por tabela (assinatura do caminho); sem escolha vale o mais curto */\n  relation_paths?: Record<string, string>\n  // Fase 4 — interações\n  /** clicar numa barra/fatia deste gráfico filtra os widgets que respondem ao filtro cruzado */\n  cross_source?: boolean\n  /** este widget responde aos filtros cruzados dos outros gráficos */\n  cross_target?: boolean\n  /** clicar numa barra/fatia permite \"detalhar\": próximo nível de data ou a dimensão `drill_by` */\n  drill_detail?: boolean\n  /** dimensão do próximo nível (TABELA.COLUNA) quando o agrupamento não é uma data */\n  drill_by?: string\n  /** clicar numa barra/fatia permite ver os registros que compõem o número */\n  drill_records?: boolean\n  /** KPI sem agrupamento: variação contra o período anterior */\n  compare_previous?: boolean\n  compare_invert?: boolean\n}\n\n/** Widget já normalizado para exibir (o painel exige estes campos preenchidos). */\nexport type RuntimeBiWidget = BiWidget & {\n  title: string\n  model_id: string\n  field: string\n  calc: BiWidgetCalc | string\n  width: BiWidgetWidth | string\n}\n\nexport interface BiAnalyticsConfig {\n  widgets: BiWidget[]\n  groups?: BiGroup[]\n  allow_runtime_edit?: boolean\n  /** campo de data do filtro global de período do app exportado (ex.: 'data_pedido') */\n  date_filter_field?: string\n  // Fase 5\n  /** acesso por linha: cada regra limita as linhas de acordo com o usuário logado */\n  rls?: RlsRule[]\n  /** guarda o resultado de cada consulta por este tempo (0 = sem cache) */\n  cache_seconds?: number\n  /** atualiza o painel sozinho a cada tanto tempo (0 = desligado) */\n  refresh_seconds?: number\n  /** tempo máximo de espera de cada indicador */\n  timeout_seconds?: number\n}\n",
  "lib/bi/groups.ts": "/**\n * Agrupamentos de widgets do painel de BI.\n *\n * Modelo: `analytics_config.groups = [{ id, title }]` (a ordem do array é a ordem dos grupos na tela) e cada\n * widget aponta para o grupo por `group_id`. Widgets sem grupo (ou com grupo que não existe mais) ficam soltos, no topo.\n * A ordem do array `widgets` acompanha a tela: soltos primeiro, depois os grupos na ordem deles.\n */\n\nexport interface BiGroup { id: string; title: string }\ninterface W { id: string; group_id?: string | null }\n\nexport interface BiSection<T extends W> { group: BiGroup | null; widgets: T[] }\n\nexport function newGroupId(): string {\n  return 'grp_' + Math.random().toString(36).slice(2, 9)\n}\n\n/** Seções na ordem da tela: [soltos, ...grupos]. A seção dos soltos sempre existe (pode estar vazia). */\nexport function sectionsOf<T extends W>(widgets: T[], groups: BiGroup[]): BiSection<T>[] {\n  const known = new Set(groups.map(g => g.id))\n  const loose = widgets.filter(w => !w.group_id || !known.has(w.group_id))\n  return [\n    { group: null, widgets: loose },\n    ...groups.map(g => ({ group: g, widgets: widgets.filter(w => w.group_id === g.id) })),\n  ]\n}\n\nexport function flatten<T extends W>(sections: BiSection<T>[]): T[] {\n  return sections.flatMap(s => s.widgets)\n}\n\n/**\n * Move um widget para um grupo (null = solto) na posição `toIndex` da lista de destino\n * (o índice vale depois de tirar o widget da origem; 'end' = no fim). Devolve o array de widgets já na ordem da tela.\n */\nexport function moveWidget<T extends W>(widgets: T[], groups: BiGroup[], widgetId: string, toGroupId: string | null, toIndex: number | 'end'): T[] {\n  const moving = widgets.find(w => w.id === widgetId)\n  if (!moving) return widgets\n  const target = toGroupId && groups.some(g => g.id === toGroupId) ? toGroupId : null\n  const sections = sectionsOf(widgets.filter(w => w.id !== widgetId), groups)\n  const dest = sections.find(s => (s.group?.id ?? null) === target)\n  if (!dest) return widgets\n  const updated = { ...moving, group_id: target ?? undefined } as T\n  const at = toIndex === 'end' ? dest.widgets.length : Math.max(0, Math.min(toIndex, dest.widgets.length))\n  dest.widgets.splice(at, 0, updated)\n  return flatten(sections)\n}\n\n/** Move um grupo para outra posição na lista de grupos. */\nexport function moveGroup(groups: BiGroup[], groupId: string, toIndex: number): BiGroup[] {\n  const from = groups.findIndex(g => g.id === groupId)\n  if (from < 0) return groups\n  const next = [...groups]\n  const [g] = next.splice(from, 1)\n  next.splice(Math.max(0, Math.min(toIndex, next.length)), 0, g)\n  return next\n}\n\n/** Cria um grupo; o título pode ficar vazio (a tela mostra uma dica até o usuário digitar). */\nexport function addGroup(groups: BiGroup[], title: string, id: string = newGroupId()): BiGroup[] {\n  return [...groups, { id, title: title.trim() }]\n}\n\n/** Renomeia; um nome em branco é ignorado (o grupo mantém o nome atual). */\nexport function renameGroup(groups: BiGroup[], id: string, title: string): BiGroup[] {\n  const t = title.trim()\n  if (!t) return groups\n  return groups.map(g => (g.id === id ? { ...g, title: t } : g))\n}\n\n/** Remove o grupo; os widgets dele ficam soltos (nada é apagado). */\nexport function removeGroup<T extends W>(groups: BiGroup[], widgets: T[], id: string): { groups: BiGroup[]; widgets: T[] } {\n  const nextGroups = groups.filter(g => g.id !== id)\n  const nextWidgets = widgets.map(w => (w.group_id === id ? { ...w, group_id: undefined } : w)) as T[]\n  return { groups: nextGroups, widgets: flatten(sectionsOf(nextWidgets, nextGroups)) }\n}\n\n/** Normaliza o array de widgets para a ordem da tela (útil depois de mexer em group_id). */\nexport function normalizeOrder<T extends W>(widgets: T[], groups: BiGroup[]): T[] {\n  return flatten(sectionsOf(widgets, groups))\n}\n\n/** Texto de exibição de um grupo (um grupo recém-criado ainda não tem título). */\nexport function groupLabel(g: BiGroup): string {\n  return g.title || 'Grupo sem nome'\n}\n",
}
